/* Nepal Information Hub — Research lab › Optimization lab.
   Lagrangian multipliers (equality constraints), Karush–Kuhn–Tucker conditions (inequality constraints) and the
   Hamiltonian / Pontryagin maximum principle (dynamic control), each applied to an econometric or stock-market problem,
   run on NEPSE prices, an uploaded Excel/CSV or any dataset, with the multipliers / shadow prices reported and plotted.
   Numerics in opt-core.js (OPT); charts reuse helpers from othermod.js (omXY, sl, sp). */
'use strict';
const OPL = {model: 'mvo', p: {}, ran: {}, src: 'stock', syms: null, lastN: 750, lags: false, ds: '', cat: '', upload: null};
const OPL_GROUPS = [['lag', 'Lagrangian · equality constraints'], ['kkt', 'KKT · inequality constraints'], ['ham', 'Hamiltonian · dynamic control']];
const OPL_MODELS = [];
const opDef = m => OPL_MODELS.push(m);
const opF = (v, d = 3) => isNum(v) ? fmt(v, d) : '–', opP = p => !isNum(p) ? '–' : p < 0.001 ? '<0.001' : fmt(p, 3);
const opE = v => !isNum(v) ? '–' : v === 0 ? '0' : Math.abs(v) < 1e-3 || Math.abs(v) >= 1e7 ? v.toExponential(2) : fmt(v, 4);
const opC = (n, title, note = '', cls = '') => `<div><h3>${title}</h3>${note ? `<p class="sub" style="margin:-4px 0 6px">${note}</p>` : ''}<div class="cv ${cls}"><canvas id="op${n}"></canvas></div></div>`;
const opTbl = (head, rows, cls = '') => `<div class="tbl ${cls}"><table><thead><tr>${head.map((h, i) => `<th${i ? '' : ' class="txt"'}>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r => `<tr>${r.map((c, i) => `<td class="${i ? 'num' : 'txt'}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const opKpi = items => `<div class="kpis" style="margin:0">${items.map(([l, v, s]) => `<div class="kpi"><div class="k">${l}</div><div class="v">${v}</div>${s ? `<div class="d">${s}</div>` : ''}</div>`).join('')}</div>`;
const opCard = (title, inner, note = '') => `<div class="card wide"><h2>${title}</h2>${note ? `<p class="sub">${note}</p>` : ''}${inner}</div>`;
const opBar = (id, labels, sets, {yt = '', stacked = false, horizontal = false} = {}) => { const t = T(); mk(id, {type: 'bar', data: {labels, datasets: sets.map((s, i) => ({backgroundColor: s.color || t.s[i % 8], borderRadius: 3, ...s}))}, options: {indexAxis: horizontal ? 'y' : 'x', plugins: {legend: {display: sets.length > 1}}, scales: {x: {stacked, ticks: {maxTicksLimit: 30}}, y: {stacked, title: {display: !!yt, text: yt, color: t.ink3}}}}}); };
const opRng = (a, b, n) => Array.from({length: n}, (_, i) => a + (b - a) * i / (n - 1));

/* ------------------------------ data table for the econometric models ------------------------------ */
function opSymsDefault() { const s = qSymbols(); return s.slice(0, 6); }
function opTable() {
  if (OPL.src === 'stock') {
    const syms = (OPL.syms || opSymsDefault()).filter(s => qSymbols().includes(s)); if (!syms.length) throw new Error('Tick at least one symbol in the data panel.');
    const {R, D} = sqAligned(syms, OPL.lastN + 1); if (R.length < 30) throw new Error('Fewer than 30 common trading days for the ticked symbols.');
    const names = syms.map(s => 'r_' + s.replace(/\W+/g, '_')), cols = syms.map((_, j) => R.map(r => r[j]));
    if (OPL.lags) syms.forEach((s, j) => { names.push('L1_' + names[j]); cols.push(R.map((r, i) => i ? R[i - 1][j] : null)); });
    return {names, cols, dates: D, label: `Daily log returns (%) of ${syms.join(', ')} — ${R.length} days${OPL.lags ? ', with lag-1 columns' : ''}`};
  }
  if (OPL.src === 'upload') { if (!OPL.upload) throw new Error('Upload an Excel or CSV file in the data panel first.'); return OPL.upload; }
  const d = ds(OPL.ds); if (!d) throw new Error('Choose a dataset in the data panel.');
  const nc = numCols(d), fq = freqOf(d), rows = d.rows.filter(r => !catKeys(d).length || catLabel(d, r) === OPL.cat).slice().sort((a, b) => { const x = alignKey(d, a), y = alignKey(d, b); return x < y ? -1 : x > y ? 1 : 0; });
  if (rows.length < 8) throw new Error('That dataset/category has fewer than 8 rows.');
  return {names: nc.map(c => c.label.replace(/[^A-Za-z0-9_]+/g, '_').replace(/^_|_$/g, '').slice(0, 40) || c.k), cols: nc.map(c => rows.map(r => isNum(r[c.k]) ? r[c.k] : null)), dates: rows.map(r => fq ? qsKeyDate(fq, alignKey(d, r)) || plabel(d, r) : plabel(d, r)), label: `${d.title}${OPL.cat ? ' · ' + OPL.cat : ''} — ${rows.length} rows`};
}
function opParseUpload(aoa, name) {
  const H = aoa.findIndex(r => r.filter(c => String(c ?? '').trim() && !isNum(typeof c === 'number' ? c : parseNum(String(c)))).length >= 2); if (H < 0) throw new Error('No header row (column names) found.');
  const h = aoa[H].map((c, j) => String(c ?? '').trim() || 'col' + (j + 1)), body = aoa.slice(H + 1).filter(r => r.some(c => c !== null && c !== ''));
  const num = v => typeof v === 'number' ? v : (() => { const x = parseNum(String(v ?? '').replace(/[^\d.,eE+-]/g, '')); return isNum(x) ? x : null; })();
  const iD = h.findIndex(x => /^(date|period|year|fy|fiscal year|month|miti)$/i.test(x)), names = [], cols = [];
  h.forEach((nm, j) => { if (j === iD) return; const v = body.map(r => num(r[j])); if (v.filter(isNum).length >= Math.max(5, 0.6 * body.length)) { names.push(nm.replace(/[^A-Za-z0-9_]+/g, '_').replace(/^_|_$/g, '') || 'X' + (j + 1)); cols.push(v); } });
  if (names.length < 1) throw new Error('No numeric columns found.'); if (body.length < 8) throw new Error('Need at least 8 data rows.');
  return {names, cols, dates: body.map((r, i) => iD >= 0 ? (cellDate(r[iD]) || String(r[iD])) : String(i + 1)), label: `${name} (uploaded) — ${body.length} rows, ${names.length} numeric columns`};
}
/* y and X (with intercept) from the table, dropping rows with a missing value in any used column */
function opYX(Tb, yName, xNames, {intercept = true} = {}) {
  const iy = Tb.names.indexOf(yName); if (iy < 0) throw new Error('Choose the dependent variable (y).');
  const ix = xNames.map(n => Tb.names.indexOf(n)).filter(i => i >= 0 && i !== iy); if (!ix.length) throw new Error('Tick at least one explanatory variable (x) different from y.');
  const y = [], X = [], dates = []; Tb.cols[iy].forEach((v, i) => { const xs = ix.map(j => Tb.cols[j][i]); if (isNum(v) && xs.every(isNum)) { y.push(v); X.push(intercept ? [1, ...xs] : xs); dates.push(Tb.dates[i]); } });
  if (y.length < ix.length + 5) throw new Error(`Only ${y.length} complete rows for ${ix.length} regressors.`);
  return {y, X, names: [...(intercept ? ['const'] : []), ...ix.map(j => Tb.names[j])], dates};
}

/* ------------------------------ fields ------------------------------ */
const oN = (id, label, v) => ({id, label, type: 'n', v}), oO = (id, label, v, opts) => ({id, label, type: 'opt', v, opts}), oT = (id, label, v) => ({id, label, type: 'txt', v});
const oS = (id, label, v) => ({id, label, type: 'sym', v}), oSS = (id, label) => ({id, label, type: 'syms'}), oY = (id, label) => ({id, label, type: 'y'}), oX = (id, label) => ({id, label, type: 'xs'});
function opTblSafe() { try { return opTable(); } catch (e) { return null; } }
function opFieldHtml(m) { return opFieldHtml0(m).map(([f, h]) => f.when ? h.replace('<div class="f"', `<div data-when="${f.when[0]}:${f.when[1]}" class="f"`) : h).join(''); }
function opFieldHtml0(m) {
  const P = OPL.p[m.id] = OPL.p[m.id] || {}, Tb = m.fields.some(f => f.type === 'y' || f.type === 'xs') ? opTblSafe() : null, names = Tb ? Tb.names : [];
  return m.fields.map(f => { const v = P[f.id] ?? (typeof f.v === 'function' ? f.v() : f.v), lab = `<label for="opf_${f.id}">${f.label}</label>`;
    if (f.type === 'sym') { const syms = qSymbols(), sel = syms.includes(v) ? v : (m.symDefault && syms.includes(m.symDefault) ? m.symDefault : syms.find(s => !INDEX_SYMS.test(s)) || syms[0]); return `<div class="f">${lab}<select id="opf_${f.id}">${syms.map(s => `<option ${s === sel ? 'selected' : ''}>${esc(s)}</option>`).join('')}</select></div>`; }
    if (f.type === 'syms') { const syms = qSymbols(), cur = Array.isArray(P[f.id]) ? P[f.id] : syms.slice(0, 8); return `<div class="f" style="grid-column:1/-1">${lab}<div class="opchk" id="opf_${f.id}">${syms.map(s => `<label><input type="checkbox" value="${esc(s)}" ${cur.includes(s) ? 'checked' : ''}> ${esc(s)}</label>`).join('')}</div></div>`; }
    if (f.type === 'y') { const def = P[f.id] && names.includes(P[f.id]) ? P[f.id] : (m.yDefault ? m.yDefault(names) : names[names.length - 1]); return `<div class="f">${lab}<select id="opf_${f.id}">${names.map(n => `<option ${n === def ? 'selected' : ''}>${esc(n)}</option>`).join('') || '<option value="">(load data above)</option>'}</select></div>`; }
    if (f.type === 'xs') { const yv = P.y && names.includes(P.y) ? P.y : (m.yDefault ? m.yDefault(names) : names[names.length - 1]), cur = Array.isArray(P[f.id]) && P[f.id].some(n => names.includes(n)) ? P[f.id] : (m.xDefault ? m.xDefault(names, yv) : names.filter(n => n !== yv).slice(0, 3));
      return `<div class="f" style="grid-column:1/-1">${lab}<div class="opchk" id="opf_${f.id}">${names.map(n => `<label><input type="checkbox" value="${esc(n)}" ${cur.includes(n) ? 'checked' : ''}> ${esc(n)}</label>`).join('') || '<span class="sub">Load data in the panel above.</span>'}</div></div>`; }
    if (f.type === 'opt') return `<div class="f">${lab}<select id="opf_${f.id}">${f.opts.map(o => { const [ov, ol] = Array.isArray(o) ? o : [o, o]; return `<option value="${esc(String(ov))}" ${String(ov) === String(v) ? 'selected' : ''}>${esc(ol)}</option>`; }).join('')}</select></div>`;
    if (f.type === 'txt') return `<div class="f" style="grid-column:1/-1">${lab}<textarea id="opf_${f.id}" rows="4" style="width:100%;font-family:JetBrains Mono,monospace;font-size:12px">${esc(String(v ?? ''))}</textarea></div>`;
    return `<div class="f">${lab}<input id="opf_${f.id}" value="${esc(String(v ?? ''))}" inputmode="decimal"></div>`; }).map((h, i) => [m.fields[i], h]);
}
function opWhen() { document.querySelectorAll('#p-opt [data-when]').forEach(el => { const [id, val] = el.dataset.when.split(':'), src = document.getElementById('opf_' + id); el.hidden = !!src && src.value !== val; }); }
function opRead(m) { const P = OPL.p[m.id] = OPL.p[m.id] || {}; m.fields.forEach(f => { const el = document.getElementById('opf_' + f.id); if (!el) return;
  if (f.type === 'syms' || f.type === 'xs') P[f.id] = [...el.querySelectorAll('input:checked')].map(x => x.value);
  else if (f.type === 'n') P[f.id] = el.value.trim() === '' ? null : +el.value; else P[f.id] = el.value; }); }
function opVals(m) { const P = OPL.p[m.id] || {}, o = {}; m.fields.forEach(f => { let v = P[f.id]; if (v === undefined) { const el = document.getElementById('opf_' + f.id);
    if (el && (f.type === 'syms' || f.type === 'xs')) v = [...el.querySelectorAll('input:checked')].map(x => x.value); else if (el) v = f.type === 'n' ? (el.value.trim() === '' ? null : +el.value) : el.value; else v = typeof f.v === 'function' ? f.v() : f.v; }
  if (f.type === 'n' && v !== null && v !== undefined && v !== '') v = +v; o[f.id] = v; }); return o; }

/* ------------------------------ page ------------------------------ */
function renderOptLab() {
  try { OPL.model = localStorage.getItem('nmm-opl') || OPL.model; } catch (e) {}
  let m = OPL_MODELS.find(x => x.id === OPL.model) || OPL_MODELS[0]; OPL.model = m.id;
  const P = $('#p-opt'), syms = qSymbols(), dsList = allDs().filter(d => numCols(d).length >= 2 && d.rows.length >= 8 && d.id !== QS_DS), chosen = OPL.syms || opSymsDefault();
  const needsTable = m.fields.some(f => f.type === 'y' || f.type === 'xs'), tb = opTblSafe();
  P.innerHTML = `<div class="card wide"><div class="chead"><div><h2>Optimization lab — Lagrangian · KKT · Hamiltonian</h2>
    <p class="sub">The three optimisation frameworks behind most of econometrics and quantitative finance, each turned into a working model on Nepali data. Equality constraints → <b>Lagrange multipliers</b> (shadow prices); inequality constraints → <b>Karush–Kuhn–Tucker</b> conditions (complementary slackness tells which limits bind); decisions over time → the <b>Hamiltonian</b> and its co-state (the shadow value of the state variable). Every model reports its multipliers and checks the optimality conditions numerically.</p></div></div>
    <details class="panel"><summary>Comparative summary of the three frameworks</summary><div>${opTbl(['Framework', 'Problem', 'Optimality conditions', 'Econometrics', 'Stock market / finance'], [
      ['Lagrangian', 'min f(x) s.t. g(x) = 0', '∇f = Σλᵢ∇gᵢ, g(x) = 0; λ = ∂f*/∂(constraint level)', 'LM / score tests (Breusch–Godfrey, Breusch–Pagan, ARCH-LM), restricted least squares', 'Analytic Markowitz frontier, GMVP, shadow price of risk'],
      ['KKT', 'min f(x) s.t. g(x) ≤ 0, h(x) = 0', 'stationarity, primal & dual feasibility (μ ≥ 0), complementary slackness μᵢgᵢ(x) = 0', 'Lasso / elastic net, Tobit (corner solutions), non-crossing quantiles', 'Long-only & capped portfolios, SVM direction classifier, option no-arbitrage bounds'],
      ['Hamiltonian', 'max ∫ f(x,u,t)dt s.t. ẋ = g(x,u,t)', 'ℋ = f + λg; ∂ℋ/∂u = 0, λ̇ = −∂ℋ/∂x, ẋ = ∂ℋ/∂λ, transversality (stochastic: HJB)', 'Ramsey–Cass–Koopmans / DSGE growth path', 'Almgren–Chriss optimal execution, Merton portfolio–consumption, American options (optimal stopping)']].map(r => r.map(c => esc(c))), 'opsum')}</div></details></div>
    <div class="card wide"><h2>Data for the econometric models</h2><p class="sub">Used by models that ask for y and x variables (LM tests, restricted least squares, Lasso, Tobit, quantile regression). Portfolio, SVM and dynamic models pick their own stocks below.</p>
    <div class="subnav" id="opSrc">${[['stock', 'Stock returns'], ['upload', 'Upload Excel / CSV'], ['dataset', 'Any dataset']].map(([k, l]) => `<button data-s="${k}" aria-selected="${OPL.src === k}">${l}</button>`).join('')}</div>
    <div class="form" style="grid-template-columns:repeat(auto-fit,minmax(170px,1fr));margin-top:10px">
    ${OPL.src === 'stock' ? `<div class="f" style="grid-column:1/-1"><label>Symbols (daily log returns, %)</label><div class="opchk" id="opSyms">${syms.map(s => `<label><input type="checkbox" value="${esc(s)}" ${chosen.includes(s) ? 'checked' : ''}> ${esc(s)}</label>`).join('')}</div></div>
      <div class="f"><label for="opN">Last N trading days (0 = all)</label><input id="opN" value="${OPL.lastN}"></div><div class="f"><label><input type="checkbox" id="opLag" ${OPL.lags ? 'checked' : ''}> Add lag-1 of every return</label></div>` : ''}
    ${OPL.src === 'upload' ? `<div class="f" style="grid-column:span 2"><label for="opFile">Excel / CSV: one header row, numeric columns (a Date / Year column is optional)</label><input id="opFile" type="file" accept=".xlsx,.xls,.csv,.txt"></div><div class="f"><label>&nbsp;</label><button class="btn small" id="opTpl">Download template</button></div>` : ''}
    ${OPL.src === 'dataset' ? `<div class="f"><label for="opDs">Dataset</label><select id="opDs">${uniq(dsList.map(d => d.group)).map(g => `<optgroup label="${esc(g)}">${dsList.filter(d => d.group === g).map(d => `<option value="${esc(d.id)}" ${d.id === OPL.ds ? 'selected' : ''}>${esc(d.title)}</option>`).join('')}</optgroup>`).join('')}</select></div><div class="f"><label for="opCat">Category</label><select id="opCat"></select></div>` : ''}
    </div><div class="actions"><button class="btn" id="opLoad">Use this data</button><span id="opDMsg">${tb ? esc(tb.label) + ' · columns: ' + esc(tb.names.slice(0, 12).join(', ')) + (tb.names.length > 12 ? '…' : '') : ''}</span></div></div>
    <div class="card wide"><h2>Models</h2><div class="ompick">${OPL_GROUPS.map(([g, gl]) => `<div class="omrow"><span class="omg">${gl}</span><div class="subnav">${OPL_MODELS.filter(x => x.g === g).map(x => `<button data-m="${x.id}" aria-selected="${x.id === m.id}">${x.name}</button>`).join('')}</div></div>`).join('')}</div></div>
    <div class="card wide"><h2>${m.name}</h2><div class="sub omintro">${m.intro}</div>${m.learn ? `<details class="panel"><summary>Learn: the optimisation behind it</summary><div class="omintro">${m.learn}</div></details>` : ''}
    <div class="form" style="grid-template-columns:repeat(auto-fit,minmax(190px,1fr))">${opFieldHtml(m)}</div><div class="actions"><button class="btn primary" id="opRun">Run model</button><span id="opMsg"></span></div></div>
    <div id="opOut" style="display:grid;gap:18px"></div>`;
  $('#opSrc').onclick = e => { const b = e.target.closest('button'); if (!b) return; OPL.src = b.dataset.s; renderOptLab(); };
  if ($('#opDs')) { const fill = () => { OPL.ds = $('#opDs').value; const d = ds(OPL.ds), cats = catKeys(d).length ? uniq(d.rows.map(r => catLabel(d, r))) : []; $('#opCat').innerHTML = cats.length ? cats.map(c => `<option ${c === OPL.cat ? 'selected' : ''}>${esc(c)}</option>`).join('') : '<option value="">(none)</option>'; OPL.cat = $('#opCat').value; };
    if (!OPL.ds || !ds(OPL.ds)) OPL.ds = $('#opDs').value; $('#opDs').value = OPL.ds; fill(); $('#opDs').onchange = () => { OPL.cat = ''; fill(); }; $('#opCat').onchange = e => { OPL.cat = e.target.value; }; }
  if ($('#opFile')) $('#opFile').onchange = async e => { const f = e.target.files[0]; if (!f) return; try { const sh = await parseFileBuffer(f.name, await f.arrayBuffer()); const aoa = sh.find(s => s.aoa && s.aoa.length > 8)?.aoa; if (!aoa) throw new Error('No data sheet with 8+ rows found.'); OPL.upload = opParseUpload(aoa, f.name.replace(/\.[^.]+$/, '')); OPL.p = {}; renderOptLab(); } catch (er) { msg('#opDMsg', er.message, 'err'); } };
  if ($('#opTpl')) $('#opTpl').onclick = () => { const wb = XLSX.utils.book_new(); XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([['Year', 'ln_Output', 'ln_Capital', 'ln_Labour', 'Y_censored', 'X1', 'X2'], ['2015', '', '', '', '', '', '']]), 'Data');
    XLSX.utils.book_append_sheet(wb, XLSX.utils.aoa_to_sheet([['How to use'], ['Row 1 = column names. Every numeric column becomes a variable you can pick as y or x.'], ['Example: a Cobb–Douglas production function — regress ln_Output on ln_Capital and ln_Labour, then in Restricted least squares type  ln_Capital + ln_Labour = 1  to impose constant returns to scale.'], ['Y_censored: a variable with a floor or ceiling (spending that is 0 for many households, a credit limit, a price-limit hit) — use it in Tobit with the matching limit.']]), 'How to use');
    XLSX.writeFile(wb, 'Optimization_Lab_Template.xlsx'); };
  $('#opLoad').onclick = () => { if (OPL.src === 'stock') { OPL.syms = [...$('#opSyms').querySelectorAll('input:checked')].map(x => x.value); const n = parseInt($('#opN').value, 10); OPL.lastN = n >= 0 ? n : 750; OPL.lags = $('#opLag').checked; }
    try { const t = opTable(); OPL.p = Object.fromEntries(Object.entries(OPL.p).map(([k, v]) => [k, Object.fromEntries(Object.entries(v).filter(([kk]) => kk !== 'y' && kk !== 'xs'))])); renderOptLab(); msg('#opDMsg', t.label + ' · columns: ' + t.names.slice(0, 12).join(', '), 'ok'); } catch (er) { msg('#opDMsg', er.message, 'err'); } };
  P.querySelector('.ompick').onclick = e => { const x = e.target.closest('button[data-m]'); if (!x) return; OPL.model = x.dataset.m; try { localStorage.setItem('nmm-opl', OPL.model); } catch (er) {} renderOptLab(); };
  const yEl = $('#opf_y'); if (yEl) yEl.onchange = () => { opRead(m); const P2 = OPL.p[m.id]; delete P2.xs; renderOptLab(); };
  opWhen(); P.querySelectorAll('select[id^="opf_"]').forEach(el => el.addEventListener('change', opWhen));
  $('#opRun').onclick = () => { opRead(m); opTry(() => opRun(m)); };
  if (OPL.ran[m.id]) opTry(() => opRun(m));
}
async function opTry(fn) { msg('#opMsg', 'Working…'); await new Promise(r => setTimeout(r, 20)); try { await fn(); msg('#opMsg', ''); } catch (e) { if (/is not a function|undefined|null/.test(e.message)) console.error(e); msg('#opMsg', e.message, 'err'); } }
async function opRun(m) { const out = $('#opOut'), v = opVals(m); OPL.ran[m.id] = true; out.innerHTML = '<div class="card wide"><div class="empty">Running…</div></div>'; await new Promise(r => setTimeout(r, 15));
  try { await m.run(v, out); } catch (e) { OPL.ran[m.id] = false; out.innerHTML = ''; throw e; } }
const opYDef = names => names.find(n => /NABIL/i.test(n) && !/^L1_/.test(n)) || names.filter(n => !/^L1_/.test(n)).slice(-1)[0] || names[0];
const opXDef = (names, y) => names.filter(n => n !== y && !/^L1_/.test(n)).slice(0, 2);
function opMoments(syms, lastN) { const {R, D} = sqAligned(syms, lastN); if (R.length < 60) throw new Error('Fewer than 60 common trading days for these symbols.'); const m = syms.length, mu = syms.map((_, j) => ST.mean(R.map(r => r[j]))), C = syms.map((_, a) => syms.map((_, b) => { let s = 0; for (const r of R) s += (r[a] - mu[a]) * (r[b] - mu[b]); return s / (R.length - 1); })); return {mu, C, R, D, n: R.length}; }
function opPortIn(v) { // annualised μ and Σ (decimal) from stocks or manual text
  if (v.src === 'manual') { const rows = String(v.manual || '').split(/\n+/).map(l => l.split(/[,;\t]+/).map(s => s.trim())).filter(r => r.length >= 3 && isNum(+r[1]) && isNum(+r[2])); if (rows.length < 2) throw new Error('Manual inputs: give at least two lines "Name, expected return %, volatility %".');
    const rho = Math.max(-0.99, Math.min(0.99, +v.rho || 0)), names = rows.map(r => r[0]), mu = rows.map(r => +r[1] / 100), sd = rows.map(r => +r[2] / 100); return {names, mu, C: sd.map((a, i) => sd.map((b, j) => i === j ? a * a : rho * a * b)), note: `manual inputs, constant correlation ${rho}`}; }
  const syms = (v.syms || []).filter(s => qSymbols().includes(s)); if (syms.length < 2) throw new Error('Tick at least two symbols.');
  const M = opMoments(syms, v.n > 0 ? v.n : 0), A = 240; return {names: syms, mu: M.mu.map(x => x / 100 * A), C: M.C.map(r => r.map(x => x / 1e4 * A)), note: `${M.n} daily returns to ${M.D[M.D.length - 1]}, annualised ×240`, n: M.n};
}

/* ================================== LAGRANGIAN ================================== */
opDef({g: 'lag', id: 'lm', name: 'LM (score) tests',
  intro: `Lagrange-multiplier tests estimate only the <b>restricted</b> model (the null) and ask whether the slope of the log-likelihood there — the score s(θ̃) — is too steep to be zero: <b>LM = s(θ̃)′ 𝓘(θ̃)⁻¹ s(θ̃) ~ χ²ᵣ</b>. In regression this collapses to n·R² of an auxiliary regression of the residuals. Breusch–Godfrey (serial correlation), Breusch–Pagan (heteroskedasticity) and Engle’s ARCH-LM (volatility clustering) are all LM tests.`,
  learn: `Maximise ℓ(θ) subject to the restriction h(θ) = 0 with ℒ = ℓ(θ) − λ′h(θ). At the restricted optimum s(θ̃) = H′λ̃: the multiplier is large exactly when the score is far from zero, so testing λ = 0 and testing s(θ̃) = 0 are the same thing. Because only the null model is fitted, LM tests are the cheapest of the trinity (Wald needs the unrestricted model, LR needs both).<br><b>Breusch–Godfrey</b>: H₀ no autocorrelation up to lag p — regress eₜ on xₜ and eₜ₋₁…eₜ₋ₚ, LM = n·R² ~ χ²ₚ. <b>Breusch–Pagan</b> (Koenker): regress e² on x, LM = n·R² ~ χ²ₖ₋₁. <b>ARCH-LM</b>: regress e²ₜ on e²ₜ₋₁…e²ₜ₋q, LM = (n−q)·R² ~ χ²_q. Rejection means OLS standard errors are wrong — use HAC (Newey–West) or GARCH.`,
  yDefault: opYDef, xDefault: opXDef,
  fields: [oY('y', 'Dependent variable y'), oX('xs', 'Explanatory variables x'), oN('bg', 'Breusch–Godfrey lags p', 4), oN('arch', 'ARCH-LM lags q', 4)],
  run(v, out) { const Tb = opTable(), {y, X, names, dates} = opYX(Tb, v.y, v.xs || []), r = OPT.lmTests(y, X, {bg: Math.max(1, Math.round(v.bg || 4)), arch: Math.max(1, Math.round(v.arch || 4))}), f = r.fit, t = T();
    const verdict = (p, yes, no) => !isNum(p) ? '–' : p < 0.05 ? `<b>${yes}</b>` : no;
    out.innerHTML = opCard('OLS on the null model', opTbl(['Variable', 'Coefficient', 'Std. error', 't', 'p-value'], names.map((nm, i) => [esc(nm), opF(f.coef[i], 4), opF(f.se[i], 4), opF(f.t[i], 2), opP(f.p[i])])) + `<p class="sub">n = ${f.n} · R² = ${opF(f.r2, 4)} · Durbin–Watson = ${opF(f.dw, 3)}</p>`)
      + opCard('Lagrange-multiplier tests', opTbl(['Test (H₀)', 'Auxiliary regression', 'LM statistic', 'df', 'p-value', 'Auxiliary R²', 'Reading at 5%'], [
        [`Breusch–Godfrey (no autocorrelation to lag ${r.bg.lags})`, `e on x, e₋₁…e₋${r.bg.lags}`, opF(r.bg.LM, 3), r.bg.df, opP(r.bg.p), opF(r.bg.r2, 4), verdict(r.bg.p, 'serial correlation — use HAC SEs or add lags', 'no evidence of serial correlation')],
        ['Breusch–Pagan, Koenker (homoskedastic)', 'e² on x', opF(r.bp.LM, 3), r.bp.df, opP(r.bp.p), opF(r.bp.r2, 4), verdict(r.bp.p, 'heteroskedastic — use robust (HC) SEs', 'no evidence of heteroskedasticity')],
        [`ARCH-LM (no ARCH to lag ${r.arch.lags})`, `e² on e²₋₁…e²₋${r.arch.lags}`, opF(r.arch.LM, 3), r.arch.df, opP(r.arch.p), opF(r.arch.r2, 4), verdict(r.arch.p, 'volatility clustering — model with GARCH', 'no ARCH effects')]]),
        'Each statistic is n·R² of the auxiliary regression — the score form s′𝓘⁻¹s evaluated at the restricted (null) estimates.')
      + `<div class="card wide"><div class="grid2">${opC(1, 'Residual autocorrelation', 'Bars outside the band (±1.96/√n) are what Breusch–Godfrey picks up.')}${opC(2, 'Squared residuals over time', 'Bursts of large squared residuals are what ARCH-LM picks up.')}${opC(3, 'Squared residual vs fitted value', 'A fan shape is what Breusch–Pagan picks up.')}${opC(4, 'Residuals', '')}</div></div>`;
    const ac = ST.acf(f.res, 20).slice(1), band = 1.96 / Math.sqrt(f.n);
    mk('op1', {type: 'bar', data: {labels: ac.map((_, i) => i + 1), datasets: [{label: 'ACF', data: ac, backgroundColor: ac.map(a => Math.abs(a) > band ? t.crit : t.s[0])}, {type: 'line', label: '+band', data: ac.map(() => band), borderColor: t.ink3, borderDash: [4, 4], pointRadius: 0}, {type: 'line', label: '−band', data: ac.map(() => -band), borderColor: t.ink3, borderDash: [4, 4], pointRadius: 0}]}, options: {plugins: {legend: {display: false}}, scales: {x: {title: {display: true, text: 'lag'}}, y: {}}}});
    mk('op2', {type: 'line', data: {labels: dates, datasets: [{label: 'e²', data: f.res.map(e => e * e), borderColor: t.s[1], pointRadius: 0, borderWidth: 1}]}, options: {plugins: {legend: {display: false}}, scales: {x: {ticks: {maxTicksLimit: 8}}, y: {}}}});
    omXY('op3', [sp('obs', f.fit.map((x, i) => ({x, y: f.res[i] ** 2})), t.s[2], {pointRadius: 2})], {xt: 'fitted', yt: 'e²', legend: false});
    mk('op4', {type: 'line', data: {labels: dates, datasets: [{label: 'e', data: f.res, borderColor: t.s[0], pointRadius: 0, borderWidth: 1}]}, options: {plugins: {legend: {display: false}}, scales: {x: {ticks: {maxTicksLimit: 8}}, y: {}}}});
  }});

opDef({g: 'lag', id: 'rls', name: 'Restricted least squares & trinity',
  intro: `Impose theory on a regression — constant returns to scale in a Cobb–Douglas function (β<sub>K</sub> + β<sub>L</sub> = 1), betas that sum to one, a coefficient fixed at a value — with the Lagrangian <b>ℒ = ½‖y − Xβ‖² − λ′(Rβ − r)</b>. Solution: β<sub>R</sub> = β̂ − (X′X)⁻¹R′[R(X′X)⁻¹R′]⁻¹(Rβ̂ − r) and λ = [R(X′X)⁻¹R′]⁻¹(r − Rβ̂). λ is the <b>shadow price</b> of the restriction: how much the minimised ½SSR changes per unit change in r. Wald, LR and LM tests of the restriction are reported (in the linear model W ≥ LR ≥ LM).`,
  learn: `Write restrictions as text, one per line or separated by “;”: coefficients are <code>b0</code> (intercept), <code>b1</code>, <code>b2</code>, … in the order of the variable list, or use the variable names, e.g. <code>ln_Capital + ln_Labour = 1</code>, <code>b2 = 0</code>, <code>2*b1 - b3 = 0</code>.<br>Envelope theorem: d(½SSR*)/dr = λ. A multiplier near 0 means the data barely object to the restriction; a large |λ| relative to its standard error means the restriction is expensive (the same information as the Wald / LM tests). The chart traces ½SSR* as the right-hand side r is moved and draws the tangent with slope λ.<br>Cobb–Douglas: use <b>Upload Excel</b> with ln Output, ln Capital, ln Labour (template provided) or any dataset with logged series.`,
  yDefault: opYDef, xDefault: opXDef,
  fields: [oY('y', 'Dependent variable y'), oX('xs', 'Explanatory variables x'), oT('restr', 'Restrictions (one per line)', 'b1 + b2 = 1')],
  run(v, out) { const Tb = opTable(), {y, X, names} = opYX(Tb, v.y, v.xs || []), pr = OPT.parseRestr(v.restr, names), r = OPT.rls(y, X, pr.R, pr.r, names), t = T();
    out.innerHTML = opKpi([['F test', opF(r.F, 3), 'p ' + opP(r.Fp)], ['Wald', opF(r.W, 3), 'p ' + opP(r.Wp)], ['Likelihood ratio', opF(r.LR, 3), 'p ' + opP(r.LRp)], ['Lagrange multiplier', opF(r.LM, 3), 'p ' + opP(r.LMp)], ['LM via score s′𝓘⁻¹s', opF(r.LMscore, 3), 'identical to n·(SSRᵣ−SSRᵤ)/SSRᵣ']])
      + opCard('Unrestricted vs restricted estimates', opTbl(['Coefficient', 'Name', 'Unrestricted β̂', 'SE', 'Restricted β_R', 'SE', 'Change'], names.map((nm, i) => [`b${i}`, esc(nm), opF(r.u.coef[i], 4), opF(r.u.se[i], 4), opF(r.bR[i], 4), opF(r.seR[i], 4), opF(r.bR[i] - r.u.coef[i], 4)])) + `<p class="sub">SSR unrestricted ${opF(r.ssrU, 3)} → restricted ${opF(r.ssrR, 3)} · n = ${r.n}, k = ${r.k}, q = ${r.q} restriction(s).</p>`)
      + opCard('Lagrange multipliers (shadow prices of the restrictions)', opTbl(['Restriction', 'Rβ̂ − r (violation by the free fit)', 'λ', 'SE(λ)', 'z', 'p-value', 'Reading'], pr.labels.map((l, i) => [esc(l), opF(r.dev[i], 4), opF(r.lam[i], 3), opF(r.lamSe[i], 3), opF(r.lamZ[i], 2), opP(r.lamP[i]), r.lamP[i] < 0.05 ? '<b>binding: the data reject it</b>' : 'cheap: the data accept it'])), 'λ = d(½SSR*)/dr — the increase in half the residual sum of squares per unit tightening of the restriction.')
      + `<div class="card wide"><div class="grid2">${opC(1, 'Shadow price: ½SSR* as the restriction level r moves', `First restriction “${esc(pr.labels[0])}”; dashed line has slope λ (envelope theorem).`)}${opC(2, 'Coefficients: free vs restricted', '')}</div></div>`;
    const r0 = pr.r[0], span = Math.max(Math.abs(r.dev[0]) * 2.5, 0.1 * Math.max(1, Math.abs(r0))), grid = opRng(r0 - span, r0 + span, 41), curve = grid.map(rr => { const rr2 = pr.r.slice(); rr2[0] = rr; const q = OPT.rls(y, X, pr.R, rr2, names); return {x: rr, y: q.ssrR / 2}; });
    const h0 = r.ssrR / 2; omXY('op1', [sl('½SSR*(r)', curve, t.s[0]), sl('tangent, slope λ', grid.map(x => ({x, y: h0 + r.lam[0] * (x - r0)})), t.crit, {borderDash: [5, 4], borderWidth: 1.5}), sp('your restriction', [{x: r0, y: h0}], t.s[2], {pointRadius: 6}), sp('free fit (r = Rβ̂)', [{x: r0 + r.dev[0], y: curve.reduce((a, p) => Math.min(a, p.y), Infinity)}], t.good, {pointRadius: 6})], {xt: 'restriction level r', yt: '½ SSR'});
    opBar('op2', names, [{label: 'Unrestricted', data: r.u.coef}, {label: 'Restricted', data: r.bR}], {});
  }});

opDef({g: 'lag', id: 'mvo', name: 'Analytic Markowitz frontier',
  intro: `With short sales allowed the mean–variance problem has only equality constraints, so the Lagrangian <b>ℒ = ½w′Σw − λ₁(w′μ − μ₀) − λ₂(w′1 − 1)</b> solves it in closed form: w* = λ₁Σ⁻¹μ + λ₂Σ⁻¹1 with λ₁ = (Cμ₀ − A)/D, λ₂ = (B − Aμ₀)/D, where A = 1′Σ⁻¹μ, B = μ′Σ⁻¹μ, C = 1′Σ⁻¹1, D = BC − A². The frontier is σ²(μ₀) = (Cμ₀² − 2Aμ₀ + B)/D; the global minimum-variance portfolio (GMVP) is Σ⁻¹1/C. <b>λ₁ is the shadow price of return</b>: d(½σ²)/dμ₀ = λ₁ — the extra variance you must accept per extra unit of expected return.`,
  learn: `First-order conditions: Σw = λ₁μ + λ₂1, w′μ = μ₀, w′1 = 1 — three linear equations, solved without any iterative optimiser. The two-fund theorem follows: every frontier portfolio is a mix of the GMVP and one other frontier portfolio. With a risk-free rate the tangency portfolio Σ⁻¹(μ − r<sub>f</sub>1)/1′Σ⁻¹(μ − r<sub>f</sub>1) maximises the Sharpe ratio, and on the capital market line the multiplier equals (μ<sub>T</sub> − r<sub>f</sub>)/σ²<sub>T</sub>.<br><b>NEPSE note:</b> short selling is not permitted, so the analytic frontier is a benchmark — the KKT portfolio model adds the no-short-sale and cap constraints. Expected returns estimated from history are very noisy; treat weights as illustrations of the mechanics.`,
  fields: [oO('src', 'Inputs', 'data', [['data', 'Estimate from price history'], ['manual', 'Type μ and σ manually']]), {...oSS('syms', 'Assets (≥ 2)'), when: ['src', 'data']}, {...oN('n', 'Last N days (0 = all)', 750), when: ['src', 'data']}, oN('rf', 'Risk-free rate % p.a.', () => +opF(sqRf(), 2)), oN('target', 'Target return % p.a. (blank = auto)', null), {...oT('manual', 'Manual inputs: Name, expected return % p.a., volatility % p.a.', 'Bank index, 12, 22\nHydro index, 16, 35\nInsurance index, 10, 28\nGovernment bond, 6, 4'), when: ['src', 'manual']}, {...oN('rho', 'Manual: common correlation', 0.4), when: ['src', 'manual']}],
  run(v, out) { const In = opPortIn(v), mk2 = OPT.markowitz(In.mu, In.C, (v.rf || 0) / 100), t = T(), m = In.mu.length;
    const lo = Math.min(...In.mu, mk2.gmv.mu), hi = Math.max(...In.mu), mu0 = isNum(v.target) ? v.target / 100 : (mk2.gmv.mu + hi) / 2, P0 = mk2.at(mu0);
    const h = 1e-6, dv = (mk2.at(mu0 + h).var - mk2.at(mu0 - h).var) / (2 * h) / 2;
    out.innerHTML = opKpi([['GMVP return', opF(mk2.gmv.mu * 100, 2) + '%', 'volatility ' + opF(mk2.gmv.sd * 100, 2) + '%'], ['Target μ₀', opF(mu0 * 100, 2) + '%', 'volatility ' + opF(P0.sd * 100, 2) + '%'], ['λ₁ (shadow price of return)', opF(P0.l1, 4), 'numerical d(½σ²)/dμ₀ = ' + opF(dv, 4)], ['λ₂ (shadow price of budget)', opF(P0.l2, 4), ''], ['Tangency Sharpe', mk2.tan ? opF(mk2.tan.sharpe, 3) : '–', mk2.tan ? 'return ' + opF(mk2.tan.mu * 100, 2) + '%' : 'risk-free rate ≥ GMVP return: no tangency portfolio']])
      + opCard('Frontier portfolios', opTbl(['Asset', 'μ % p.a.', 'σ % p.a.', 'GMVP weight', `Target (${opF(mu0 * 100, 2)}%) weight`, 'Tangency weight'], In.names.map((nm, i) => [esc(nm), opF(In.mu[i] * 100, 2), opF(Math.sqrt(In.C[i][i]) * 100, 2), opF(mk2.gmv.w[i] * 100, 1) + '%', opF(P0.w[i] * 100, 1) + '%', mk2.tan ? opF(mk2.tan.w[i] * 100, 1) + '%' : '–'])) + `<p class="sub">${esc(In.note)} · A = ${opE(mk2.A)}, B = ${opE(mk2.B)}, C = ${opE(mk2.C)}, D = ${opE(mk2.D)}. Negative weights are short positions (not allowed on NEPSE — see the KKT portfolio model).</p>`)
      + `<div class="card wide"><div class="grid2">${opC(1, 'Efficient frontier (closed form)', 'Assets, GMVP, target portfolio, tangency portfolio and capital market line.')}${opC(2, 'Shadow price of return λ₁ along the frontier', 'λ₁ < 0 below the GMVP (inefficient half), 0 at the GMVP, rising above it.')}${opC(3, 'Weights along the frontier', 'Linear in μ₀ — the two-fund theorem.')}${opC(4, 'Budget multiplier λ₂ along the frontier', '')}</div></div>`;
    const span = hi - lo || 0.1, g = opRng(lo - 0.3 * span, hi + 0.5 * span, 80), pts = g.map(mu => mk2.at(mu)), eff = pts.filter(p => p.mu0 >= mk2.gmv.mu), ineff = pts.filter(p => p.mu0 <= mk2.gmv.mu), ds2 = [sl('efficient frontier', eff.map(p => ({x: p.sd * 100, y: p.mu0 * 100})), t.s[0]), sl('inefficient half', ineff.map(p => ({x: p.sd * 100, y: p.mu0 * 100})), t.ink3, {borderDash: [4, 4], borderWidth: 1.5}), sp('assets', In.names.map((_, i) => ({x: Math.sqrt(In.C[i][i]) * 100, y: In.mu[i] * 100})), t.s[3], {pointRadius: 6}), sp('GMVP', [{x: mk2.gmv.sd * 100, y: mk2.gmv.mu * 100}], t.good, {pointRadius: 7}), sp('target', [{x: P0.sd * 100, y: mu0 * 100}], t.crit, {pointRadius: 7})];
    if (mk2.tan && mk2.tan.mu > (v.rf || 0) / 100) { ds2.push(sp('tangency', [{x: mk2.tan.sd * 100, y: mk2.tan.mu * 100}], t.s[5], {pointRadius: 7})); const xm = Math.max(...eff.map(p => p.sd)) * 100; ds2.push(sl('capital market line', [{x: 0, y: v.rf || 0}, {x: xm, y: (v.rf || 0) + mk2.tan.sharpe * xm}], t.s[5], {borderDash: [6, 3], borderWidth: 1.5})); }
    omXY('op1', ds2, {xt: 'volatility % p.a.', yt: 'expected return % p.a.', d: 2});
    omXY('op2', [sl('λ₁', pts.map(p => ({x: p.mu0 * 100, y: p.l1})), t.s[1]), sp('target', [{x: mu0 * 100, y: P0.l1}], t.crit, {pointRadius: 6})], {xt: 'target return μ₀ %', yt: 'λ₁', legend: false});
    omXY('op3', In.names.map((nm, i) => sl(nm, pts.map(p => ({x: p.mu0 * 100, y: p.w[i] * 100})), t.s[i % 8])), {xt: 'target return μ₀ %', yt: 'weight %', d: 1});
    omXY('op4', [sl('λ₂', pts.map(p => ({x: p.mu0 * 100, y: p.l2})), t.s[4])], {xt: 'target return μ₀ %', yt: 'λ₂', legend: false});
  }});

/* ================================== KKT ================================== */
opDef({g: 'kkt', id: 'kktp', name: 'Long-only & capped portfolio',
  intro: `The realistic NEPSE portfolio: <b>min ½w′Σw s.t. w′μ ≥ μ₀, 1′w = 1, ℓᵢ ≤ wᵢ ≤ uᵢ</b>. Inequalities need the Karush–Kuhn–Tucker conditions: stationarity Σw − λ<sub>μ</sub>μ − λ<sub>b</sub>1 − ν + ξ = 0; feasibility; dual feasibility λ<sub>μ</sub>, νᵢ, ξᵢ ≥ 0; and <b>complementary slackness</b> νᵢ(wᵢ − ℓᵢ) = 0, ξᵢ(uᵢ − wᵢ) = 0. A positive νᵢ means asset i is pushed against its floor (excluded); a positive ξᵢ means it is held at its cap — and the multiplier is the variance saved per unit the limit is relaxed.`,
  learn: `Solved exactly as a convex quadratic programme by a primal–dual interior-point method (Mehrotra predictor–corrector), which returns all multipliers. The table checks each KKT condition numerically. Use per-asset caps to mimic regulatory or mandate limits (single-issuer limits, sector caps for mutual funds, promoter-share lock-ins). The bounded frontier always lies on or to the right of the unconstrained (short-sale) frontier; the gap is the cost of the constraints, and λ<sub>μ</sub> is the slope of ½σ² along it.`,
  fields: [oO('src', 'Inputs', 'data', [['data', 'Estimate from price history'], ['manual', 'Type μ and σ manually']]), {...oSS('syms', 'Assets (≥ 2)'), when: ['src', 'data']}, {...oN('n', 'Last N days (0 = all)', 750), when: ['src', 'data']}, oN('lo', 'Minimum weight % (all assets)', 0), oN('hi', 'Maximum weight % (all assets)', 60), oT('caps', 'Per-asset caps, one per line: Name, max % (optional)', ''), oN('target', 'Target return % p.a. (blank = auto)', null), {...oT('manual', 'Manual inputs: Name, expected return % p.a., volatility % p.a.', 'Bank index, 12, 22\nHydro index, 16, 35\nInsurance index, 10, 28\nGovernment bond, 6, 4'), when: ['src', 'manual']}, {...oN('rho', 'Manual: common correlation', 0.4), when: ['src', 'manual']}],
  run(v, out) { const In = opPortIn(v), m = In.mu.length, t = T(), lo = (v.lo || 0) / 100, hiAll = (isNum(v.hi) ? v.hi : 100) / 100, U = In.names.map(() => hiAll);
    String(v.caps || '').split(/\n+/).forEach(l => { const [nm, c] = l.split(/[,;\t]+/).map(s => s.trim()); const i = In.names.findIndex(x => x.toLowerCase() === String(nm || '').toLowerCase()); if (i >= 0 && isNum(+c)) U[i] = +c / 100; });
    const base = OPT.portfolioKKT(In.mu, In.C, {mu0: null, lo, hi: U}), maxR = base.maxRet, mu0 = isNum(v.target) ? v.target / 100 : base.ret + 0.6 * Math.max(0, maxR - base.ret), r = OPT.portfolioKKT(In.mu, In.C, {mu0, lo, hi: U}), free = OPT.markowitz(In.mu, In.C, null);
    const unc = free.at(mu0);
    out.innerHTML = opKpi([['Target return', opF(mu0 * 100, 2) + '%', r.retActive ? 'constraint binding' : 'not binding (slack ' + opF(r.retSlack * 100, 2) + '%)'], ['Portfolio volatility', opF(r.sd * 100, 2) + '%', 'short-sale frontier: ' + opF(unc.sd * 100, 2) + '%'], ['λ_μ (return)', opF(r.lamRet, 4), '½σ² rises by this per unit of μ₀'], ['λ_b (budget)', opF(r.lamBud, 4), ''], ['KKT check', opE(Math.max(r.maxStat, r.maxCS)), `stationarity & slackness residual · ${r.sol.iters} IPM iterations`]])
      + opCard('Weights, active constraints and multipliers', opTbl(['Asset', 'Weight', 'Bounds', 'Status', '∂(½σ²)/∂w = (Σw)ᵢ', 'ν (floor multiplier)', 'ξ (cap multiplier)', 'νᵢ(wᵢ−ℓᵢ), ξᵢ(uᵢ−wᵢ)', 'Stationarity residual'], In.names.map((nm, i) => { const a = r.assets[i]; return [esc(nm), opF(a.w * 100, 2) + '%', `${opF(lo * 100, 0)}–${opF(U[i] * 100, 0)}%`, a.status === 'interior' ? 'interior' : `<b>${a.status}</b>`, opF(a.grad, 5), opE(a.nu), opE(a.xi), opE(a.cs), opE(a.stat)]; })) + `<p class="sub">${esc(In.note)}. Dual feasibility: smallest multiplier ${opE(r.minDual)} (must be ≥ 0). Bounds hit: ${r.assets.filter(a => a.status !== 'interior').length} of ${m}. Max reachable return under these bounds: ${opF(maxR * 100, 2)}%.</p>`)
      + `<div class="card wide"><div class="grid2">${opC(1, 'Bounded vs short-sale frontier', 'The horizontal gap is the risk cost of the constraints.')}${opC(2, 'Bounded weights along the frontier', 'Kinks appear where an asset hits a bound (the active set changes).')}${opC(3, 'Return multiplier λ_μ along the frontier', 'Bounded (solid) vs short-sale λ₁ (dashed).')}${opC(4, 'Multipliers at the target', 'Positive ν: pushed to the floor; positive ξ: held at the cap.')}</div></div>`;
    const g = opRng(base.ret, maxR - 1e-6 * Math.abs(maxR || 1), 36), sw = g.map(mu => { try { return OPT.portfolioKKT(In.mu, In.C, {mu0: mu, lo, hi: U}); } catch (e) { return null; } }).filter(Boolean);
    const fr = opRng(free.gmv.mu, Math.max(maxR, free.gmv.mu + 1e-4), 50).map(mu => free.at(mu));
    omXY('op1', [sl('bounded (KKT)', sw.map(p => ({x: p.sd * 100, y: p.ret * 100})), t.s[0]), sl('short sales allowed', fr.map(p => ({x: p.sd * 100, y: p.mu0 * 100})), t.ink3, {borderDash: [5, 4], borderWidth: 1.5}), sp('assets', In.names.map((_, i) => ({x: Math.sqrt(In.C[i][i]) * 100, y: In.mu[i] * 100})), t.s[3], {pointRadius: 6}), sp('target', [{x: r.sd * 100, y: r.ret * 100}], t.crit, {pointRadius: 7})], {xt: 'volatility % p.a.', yt: 'expected return % p.a.', d: 2});
    omXY('op2', In.names.map((nm, i) => sl(nm, sw.map(p => ({x: p.ret * 100, y: p.w[i] * 100})), t.s[i % 8])), {xt: 'target return %', yt: 'weight %', d: 1});
    omXY('op3', [sl('λ_μ bounded', sw.map(p => ({x: p.ret * 100, y: p.lamRet})), t.s[1]), sl('λ₁ short sales', fr.map(p => ({x: p.mu0 * 100, y: p.l1})), t.ink3, {borderDash: [5, 4], borderWidth: 1.5})], {xt: 'target return %', yt: 'multiplier'});
    opBar('op4', In.names, [{label: 'ν floor', data: r.assets.map(a => a.nu), color: t.s[2]}, {label: 'ξ cap', data: r.assets.map(a => a.xi), color: t.crit}], {yt: 'multiplier'});
  }});

opDef({g: 'kkt', id: 'lasso', name: 'Lasso / elastic net (KKT)',
  intro: `<b>min (1/2n)‖y − Xβ‖² + λ[α‖β‖₁ + ½(1−α)‖β‖²]</b> on standardised x. The ℓ₁ term is not differentiable at 0, so optimality is the KKT / subgradient condition: for every selected variable <b>xⱼ′r/n − λ(1−α)βⱼ = λα·sign(βⱼ)</b>, and a variable is dropped exactly when <b>|xⱼ′r/n| ≤ λα</b> — its correlation with the residual is too weak to pay the penalty. That is how lasso selects factors.`,
  learn: `Equivalent constrained form: min ‖y − Xβ‖² s.t. ‖β‖₁ ≤ t — the multiplier of that inequality is λ. Solved by cyclic coordinate descent with soft-thresholding (as glmnet / scikit-learn). λ is chosen by 5-fold cross-validation (blocked in time order for time-series data) unless you type one. Typical uses: picking which macro or market factors explain a stock’s returns, or which lags matter, from many candidates. The KKT chart shows |xⱼ′r/n| for each variable against the λα threshold: selected variables sit exactly on it, dropped ones below it.`,
  yDefault: opYDef, xDefault: (names, y) => names.filter(n => n !== y),
  fields: [oY('y', 'Dependent variable y'), oX('xs', 'Candidate predictors x'), oO('mode', 'Design', 'pred', [['pred', 'Predictive: lags 1…p of y and every x'], ['same', 'Same-period x (factor model)']]), oN('p', 'Lags p (predictive)', 5), oN('alpha', 'Mixing α (1 = lasso, 0 = ridge)', 1), oN('lam', 'Penalty λ (blank = cross-validated)', null)],
  run(v, out) { const Tb = opTable(); let {y, X, names} = opYX(Tb, v.y, v.xs || [], {intercept: false}); if (v.mode === 'pred') { const p = Math.max(1, Math.min(20, Math.round(v.p || 5))), base = [y, ...names.map((_, j) => X.map(r => r[j]))], bn = [v.y, ...names], X2 = [], y2 = [], n2 = []; bn.forEach(nm => { for (let l = 1; l <= p; l++) n2.push(`${nm}(t−${l})`); }); for (let i = p; i < y.length; i++) { X2.push(base.flatMap(c => Array.from({length: p}, (_, l) => c[i - l - 1]))); y2.push(y[i]); } y = y2; X = X2; names = n2; if (y.length < names.length + 10) throw new Error('Too few rows for that many lags.'); }
    const t = T(), alpha = Math.min(1, Math.max(0.01, isNum(v.alpha) ? v.alpha : 1));
    let lam = isNum(v.lam) && v.lam > 0 ? v.lam : null, cv = null; const pre = OPT.lasso(X, y, {alpha, lam: 1});
    if (!lam) { const K = 5, n = y.length, fold = i => Math.min(K - 1, Math.floor(i * K / n)); cv = pre.grid.map(l => { let se = 0; for (let k = 0; k < K; k++) { const tr = [], te = []; for (let i = 0; i < n; i++) (fold(i) === k ? te : tr).push(i); const f = OPT.lasso(tr.map(i => X[i]), tr.map(i => y[i]), {alpha, lam: l, nLam: 2}); te.forEach(i => { const p = f.icpt + X[i].reduce((a, x, j) => a + x * f.coefOrig[j], 0); se += (y[i] - p) ** 2; }); } return {lam: l, mse: se / n}; }); lam = cv.reduce((a, b) => b.mse < a.mse ? b : a).lam; }
    const r = OPT.lasso(X, y, {alpha, lam}), sel = r.b.filter(b => b !== 0).length;
    out.innerHTML = opKpi([['λ', opE(lam), cv ? 'chosen by 5-fold CV (time-ordered folds)' : 'typed'], ['λ_max', opE(r.lmax), 'smallest λ that drops every variable'], ['Selected', `${sel} of ${names.length}`, ''], ['Max KKT violation', opE(r.maxViol), 'should be ≈ 0']])
      + opCard('Coefficients and KKT (subgradient) conditions', opTbl(['Variable', 'β (original units)', 'β (standardised)', 'xⱼ′r/n − λ(1−α)βⱼ', 'Condition', 'Threshold λα', 'Violation'], names.map((nm, j) => { const k = r.kkt[j]; return [esc(nm), r.b[j] ? `<b>${opF(r.coefOrig[j], 5)}</b>` : '0', opF(r.b[j], 5), opF(k.g, 5), r.b[j] ? 'selected: = λα·sign(β)' : 'dropped: |·| ≤ λα', opF(lam * alpha, 5), opE(k.viol)]; })) + `<p class="sub">Intercept ${opF(r.icpt, 5)} · n = ${r.n}.</p>`)
      + `<div class="card wide"><div class="grid2">${opC(1, 'Regularisation path', 'Standardised coefficients as λ falls; the dashed line is the chosen λ.')}${opC(2, 'KKT picture at the chosen λ', 'Selected variables touch the λα line; the others stay inside it.')}${cv ? opC(3, 'Cross-validated error', '') : ''}</div></div>`;
    omXY('op1', [...names.map((nm, j) => sl(nm, r.path.map(p => ({x: Math.log10(p.lam), y: p.b[j]})), t.s[j % 8])), sl('chosen λ', [{x: Math.log10(lam), y: Math.min(...r.path.flatMap(p => p.b))}, {x: Math.log10(lam), y: Math.max(...r.path.flatMap(p => p.b))}], t.ink3, {borderDash: [4, 4], borderWidth: 1})], {xt: 'log₁₀ λ', yt: 'standardised β', legend: names.length <= 12});
    mk('op2', {type: 'bar', data: {labels: names, datasets: [{label: '|xⱼ′r/n − λ(1−α)βⱼ|', data: r.kkt.map(k => Math.abs(k.g)), backgroundColor: r.b.map(b => b ? t.s[0] : t.ink3)}, {type: 'line', label: 'λα', data: names.map(() => lam * alpha), borderColor: t.crit, borderDash: [5, 4], pointRadius: 0}]}, options: {scales: {x: {ticks: {maxTicksLimit: 30}}, y: {}}}});
    if (cv) omXY('op3', [sl('CV MSE', cv.map(c => ({x: Math.log10(c.lam), y: c.mse})), t.s[1]), sp('chosen', [{x: Math.log10(lam), y: Math.min(...cv.map(c => c.mse))}], t.crit, {pointRadius: 6})], {xt: 'log₁₀ λ', yt: 'mean squared error', legend: false, d: 4});
  }});

opDef({g: 'kkt', id: 'tobit', name: 'Tobit (censored regression)',
  intro: `When the outcome has a corner — spending is 0 for many households, a loan is capped at the credit limit, a NEPSE stock stops at its daily <b>circuit breaker</b> (±10% price band) — the observed y is a censored version of a latent y* = xβ + ε. The corner is the KKT complementary-slackness solution of the agent’s problem (either the constraint binds and y sits at the limit, or it is slack and y = y*). OLS on censored data is biased toward zero; the Tobit maximum-likelihood estimator models both regimes.`,
  learn: `Log-likelihood: Σ<sub>y=L</sub> ln Φ((L − xβ)/σ) + Σ<sub>y=U</sub> ln Φ((xβ − U)/σ) + Σ<sub>L<y<U</sub> [ln φ((y − xβ)/σ) − ln σ]. Maximised with an analytic gradient (BFGS); standard errors from the Hessian. β is the effect on the latent y*; the effect on what is observed is smaller: ∂E[y|x]/∂xⱼ = βⱼ·P(L < y* < U | x) (average marginal effect).<br><b>Circuit breaker:</b> a ±10% price band is −10.54 / +9.53 in log-return %. Values at or beyond a limit are treated as censored (a move far beyond the band usually means an un-adjusted bonus or rights issue). If no observation is censored, Tobit equals OLS — choose limits that actually bind in your data.`,
  yDefault: opYDef, xDefault: opXDef,
  fields: [oY('y', 'Dependent variable y'), oX('xs', 'Explanatory variables x'), oN('L', 'Lower limit (blank = none)', -10.54), oN('U', 'Upper limit (blank = none)', 9.53)],
  run(v, out) { const Tb = opTable(), {y, X, names} = opYX(Tb, v.y, v.xs || []), L = isNum(v.L) ? v.L : null, U = isNum(v.U) ? v.U : null, t = T();
    if (L === null && U === null) throw new Error('Give at least one limit (lower or upper).'); if (L !== null && U !== null && L >= U) throw new Error('The lower limit must be below the upper limit.');
    const yc = y.map(x => L !== null && x < L ? L : U !== null && x > U ? U : x), r = OPT.tobit(yc, X, {L, U}), k = names.length;
    out.innerHTML = opKpi([['Censored at lower limit', String(r.nCensLo), L !== null ? 'y ≤ ' + opF(L, 2) : ''], ['Censored at upper limit', String(r.nCensHi), U !== null ? 'y ≥ ' + opF(U, 2) : ''], ['σ (latent error)', opF(r.sigma, 4), 'OLS s = ' + opF(r.ols.s, 4)], ['Log-likelihood', opF(r.ll, 2), 'AIC ' + opF(r.aic, 1)], ['Gradient at optimum', opE(r.gradMax), r.gradMax < 1e-4 ? 'converged' : 'check convergence']])
      + (r.nCensLo + r.nCensHi === 0 ? '<div class="card wide"><p class="sub"><b>No observation is censored at these limits</b>, so Tobit reproduces OLS. Pick limits that bind (e.g. 0 for a variable with many zeros).</p></div>' : '')
      + opCard('Tobit vs OLS', opTbl(['Variable', 'Tobit β (latent)', 'SE', 'z', 'p-value', 'Avg. marginal effect on observed y', 'OLS β (biased)'], names.map((nm, j) => [esc(nm), opF(r.b[j], 4), opF(r.se[j], 4), opF(r.z[j], 2), opP(r.p[j]), j ? opF(r.ame[j], 4) : '–', opF(r.ols.coef[j], 4)])), `n = ${r.n}; ${r.nCensLo + r.nCensHi} censored (${opF(100 * (r.nCensLo + r.nCensHi) / r.n, 1)}%).`)
      + `<div class="card wide"><div class="grid2">${opC(1, `Observed y vs ${esc(names[1])}`, 'Censored points sit on the limit lines; Tobit latent line vs OLS line.')}${opC(2, 'Probability of being uncensored, P(L < y* < U | x)', 'The factor that shrinks β into the marginal effect on observed y.')}</div></div>`;
    const x1 = X.map(r2 => r2[1]), mx = X[0].map((_, j) => ST.mean(X.map(r2 => r2[j]))), xs = opRng(Math.min(...x1), Math.max(...x1), 40), line = (b) => xs.map(x => ({x, y: b[0] + b[1] * x + mx.slice(2).reduce((a, m2, j) => a + m2 * b[j + 2], 0)}));
    const cen = yc.map((v2, i) => ({x: x1[i], y: v2, c: (L !== null && v2 <= L + 1e-12) || (U !== null && v2 >= U - 1e-12)}));
    const sets = [sp('uncensored', cen.filter(p => !p.c), t.s[0], {pointRadius: 2}), sp('censored', cen.filter(p => p.c), t.crit, {pointRadius: 4}), sl('Tobit latent E[y*|x]', line(r.b), t.s[2]), sl('OLS', line(r.ols.coef), t.ink3, {borderDash: [5, 4]})];
    if (L !== null) sets.push(sl('lower limit', [{x: xs[0], y: L}, {x: xs[xs.length - 1], y: L}], t.s[5], {borderWidth: 1})); if (U !== null) sets.push(sl('upper limit', [{x: xs[0], y: U}, {x: xs[xs.length - 1], y: U}], t.s[5], {borderWidth: 1}));
    omXY('op1', sets, {xt: names[1], yt: 'y'});
    const pin = xs.map(x => { const xb = line(r.b).find(p => p.x === x).y; return {x, y: (U !== null ? ST.normCdf((U - xb) / r.sigma) : 1) - (L !== null ? ST.normCdf((L - xb) / r.sigma) : 0)}; });
    omXY('op2', [sl('P(uncensored)', pin, t.s[1])], {xt: names[1], yt: 'probability', legend: false, ymin: 0, ymax: 1});
  }});

opDef({g: 'kkt', id: 'qreg', name: 'Non-crossing quantile regression',
  intro: `Quantile regression estimates q<sub>τ</sub>(y|x) = xβ<sub>τ</sub> by minimising the check loss Σρ<sub>τ</sub>(y − xβ) — e.g. τ = 0.05 gives a regression-based Value-at-Risk line. Estimated separately, quantile lines can <b>cross</b> (a 5% quantile above the 10% one), which is impossible. Imposing <b>xᵢβ<sub>τ(j+1)</sub> ≥ xᵢβ<sub>τj</sub></b> at every observation is an inequality-constrained problem: KKT multipliers are positive exactly at the points where the monotonicity constraint binds.`,
  learn: `Free fits by iteratively re-weighted least squares (as statsmodels QuantReg). The joint constrained fit uses the method of multipliers on a smoothed check loss with the smoothing shrunk to zero; the multipliers μᵢ ≥ 0 and constraints satisfy complementary slackness μᵢ·cᵢ(β) = 0. Use returns of a stock on the market return (or on lagged volatility) for a conditional VaR fan; with macro data, use a growth-at-risk style regression.`,
  yDefault: opYDef, xDefault: (names, y) => opXDef(names, y).slice(0, 1),
  fields: [oY('y', 'Dependent variable y'), oX('xs', 'Explanatory variables x (the first is plotted)'), oT('taus', 'Quantiles τ', '0.05, 0.1, 0.25, 0.5, 0.75, 0.9, 0.95')],
  run(v, out) { const Tb = opTable(), {y, X, names} = opYX(Tb, v.y, v.xs || []), t = T(), taus = uniq(String(v.taus).split(/[,\s]+/).map(Number).filter(x => x > 0 && x < 1)).sort((a, b) => a - b);
    if (taus.length < 2) throw new Error('Give at least two quantiles between 0 and 1.'); if (y.length > 3000) throw new Error('Use at most 3,000 observations (reduce N in the data panel).');
    const r = OPT.qregNonCross(y, X, taus), k = names.length;
    out.innerHTML = opKpi([['Crossings (free fits)', String(r.crossFree), 'pairs of adjacent quantiles × observations'], ['Crossings (constrained)', String(r.crossCon), ''], ['Binding constraints', String(r.active.reduce((a, b) => a + b, 0)), 'observations with μ > 0'], ['Total check loss', opF(r.lossCon.reduce((a, b) => a + b, 0), 2), 'free: ' + opF(r.lossFree.reduce((a, b) => a + b, 0), 2)]])
      + opCard('Coefficients by quantile', opTbl(['τ', ...names.flatMap(n => [esc(n) + ' free', esc(n) + ' non-crossing']), 'Check loss free', 'constrained', 'Binding with next τ'], taus.map((tau, j) => [opF(tau, 2), ...names.flatMap((_, a) => [opF(r.free[j][a], 4), opF(r.con[j][a], 4)]), opF(r.lossFree[j], 3), opF(r.lossCon[j], 3), j < taus.length - 1 ? String(r.active[j]) : '–'])))
      + `<div class="card wide"><div class="grid2">${opC(1, `Quantile lines against ${esc(names[1])}`, 'Dashed: separate (free) fits; solid: jointly constrained, non-crossing fits.')}${opC(2, `Slope on ${esc(names[1])} across quantiles`, 'How the effect differs in the tails.')}</div></div>`;
    const x1 = X.map(r2 => r2[1]), mx = X[0].map((_, j) => ST.mean(X.map(r2 => r2[j]))), xs = opRng(Math.min(...x1), Math.max(...x1), 30), ln = b => xs.map(x => ({x, y: b[0] + b[1] * x + mx.slice(2).reduce((a, m2, j) => a + m2 * b[j + 2], 0)}));
    omXY('op1', [sp('data', x1.map((x, i) => ({x, y: y[i]})), t.line, {pointRadius: 1.5}), ...taus.flatMap((tau, j) => [sl('τ=' + tau, ln(r.con[j]), t.s[j % 8]), sl('', ln(r.free[j]), t.s[j % 8], {borderDash: [4, 4], borderWidth: 1})])], {xt: names[1], yt: v.y, legend: false});
    omXY('op2', [sl('free', taus.map((tau, j) => ({x: tau, y: r.free[j][1]})), t.ink3, {borderDash: [4, 4], pointRadius: 3}), sl('non-crossing', taus.map((tau, j) => ({x: tau, y: r.con[j][1]})), t.s[0], {pointRadius: 3})], {xt: 'τ', yt: 'slope'});
  }});

opDef({g: 'kkt', id: 'svm', name: 'SVM market-direction classifier',
  intro: `A soft-margin support vector machine predicts whether tomorrow is an up day. Its training problem is solved through the <b>dual</b>: max Σαᵢ − ½ΣΣαᵢαⱼyᵢyⱼK(xᵢ,xⱼ) s.t. 0 ≤ αᵢ ≤ C, Σαᵢyᵢ = 0. KKT conditions sort every training day into three groups: <b>α = 0</b> (outside the margin, y·f ≥ 1, irrelevant), <b>0 < α < C</b> (on the margin, y·f = 1, “free” support vectors) and <b>α = C</b> (inside the margin or misclassified, y·f ≤ 1). Only support vectors define the decision boundary.`,
  learn: `Solved by sequential minimal optimisation (SMO) with maximal-violating-pair selection, as in LIBSVM. Features (standardised on the training part): yesterday’s and the day-before’s return, 5-day momentum, 20-day volatility, the market’s return yesterday and the change in log volume. Chronological split: fit on the first part, test on the rest. <b>Honest reading:</b> daily direction is close to a coin toss; compare accuracy with the up-day base rate before drawing any conclusion. A linear kernel often collapses to w ≈ 0 (all days are support vectors) — that itself is the KKT signal that the classes are not separable.`,
  symDefault: 'NABIL',
  fields: [oS('sym', 'Stock / index'), oN('n', 'Last N days', 900), oN('split', 'Training share %', 70), oO('kernel', 'Kernel', 'rbf', [['rbf', 'RBF (Gaussian)'], ['linear', 'Linear']]), oN('C', 'Penalty C', 1), oN('gamma', 'RBF γ (blank = 1/features)', null)],
  run(v, out) { const S = qSeries(v.sym), mkt = qSymbols().includes('NEPSE') && v.sym !== 'NEPSE' ? qSeries('NEPSE') : null, mm = mkt ? new Map(mkt.date.map((d, i) => [d, mkt.c[i]])) : null, t = T();
    const r = [], d = [], vol = []; for (let i = 1; i < S.c.length; i++) if (S.c[i] > 0 && S.c[i - 1] > 0) { r.push(100 * Math.log(S.c[i] / S.c[i - 1])); d.push(S.date[i]); vol.push(Math.log(1 + Math.max(0, S.v[i] || 0)) - Math.log(1 + Math.max(0, S.v[i - 1] || 0))); }
    const mr = d.map((dt, i) => { if (!mm || !i) return 0; const a = mm.get(dt), b = mm.get(d[i - 1]); return a > 0 && b > 0 ? 100 * Math.log(a / b) : 0; });
    const rows = []; for (let i = 21; i < r.length; i++) { const w = r.slice(i - 20, i), m5 = r.slice(i - 5, i).reduce((a, b) => a + b, 0); rows.push({x: [r[i - 1], r[i - 2], m5, ST.sd(w), mr[i - 1], vol[i - 1]], y: r[i] > 0 ? 1 : -1, ret: r[i], d: d[i]}); }
    const use = rows.slice(-Math.max(200, Math.min(v.n || 900, 1500))), nTr = Math.round(use.length * Math.min(0.9, Math.max(0.5, (v.split || 70) / 100))), tr = use.slice(0, nTr), te = use.slice(nTr);
    const fn = ['r(t−1)', 'r(t−2)', '5-day momentum', '20-day volatility', 'market r(t−1)', 'Δ log volume'], k = fn.length, mu = fn.map((_, j) => ST.mean(tr.map(o => o.x[j]))), sd = fn.map((_, j) => ST.sd(tr.map(o => o.x[j])) || 1), z = o => o.x.map((x, j) => (x - mu[j]) / sd[j]);
    const C = Math.max(1e-3, v.C || 1), res = OPT.svmDual(tr.map(z), tr.map(o => o.y), {C, kernel: v.kernel, gamma: isNum(v.gamma) && v.gamma > 0 ? v.gamma : null, tol: 1e-4});
    const fte = res.predict(te.map(z)), acc = (f, set) => set.filter((o, i) => (f[i] > 0 ? 1 : -1) === o.y).length / set.length, base = te.filter(o => o.y > 0).length / te.length;
    const strat = te.map((o, i) => (fte[i] > 0 ? 1 : 0) * o.ret / 100), bh = te.map(o => o.ret / 100), ps = sqPerf(strat), pb = sqPerf(bh);
    out.innerHTML = opKpi([['Test accuracy', opF(acc(fte, te) * 100, 1) + '%', `always-predict-majority baseline ${opF(Math.max(base, 1 - base) * 100, 1)}% (up days ${opF(base * 100, 1)}%) · ${te.length} test days`], ['Training accuracy', opF(acc(res.f, tr) * 100, 1) + '%', `${tr.length} days`], ['Support vectors', `${res.sv.length} of ${tr.length}`, `${res.nFree} on the margin · ${res.nBound} at α = C`], ['Max KKT violation', opE(res.maxViol), `${res.iters} SMO steps · dual ${opF(res.dual, 3)}`], ['Long-when-up strategy', opF(ps.total * 100, 1) + '%', 'buy & hold ' + opF(pb.total * 100, 1) + '% (before costs)']])
      + (res.w ? opCard('Linear decision function f(x) = w′x + b', opTbl(['Feature (standardised)', 'w'], fn.map((f, j) => [esc(f), opF(res.w[j], 5)])) + `<p class="sub">b = ${opF(res.b, 5)}${Math.max(...res.w.map(Math.abs)) < 1e-3 ? ' — <b>w ≈ 0: the classes are not linearly separable; the SVM predicts the majority class.</b>' : ''}</p>`) : '')
      + `<div class="card wide"><div class="grid2">${opC(1, 'The KKT picture: margin y·f(x) vs α', 'α = 0 ⇒ y·f ≥ 1; 0 < α < C ⇒ y·f = 1; α = C ⇒ y·f ≤ 1.')}${opC(2, 'Distribution of α', '')}${opC(3, 'Test period: long when f > 0 vs buy & hold', 'Growth of Rs 1, no trading costs.')}${opC(4, 'Training days in the first two features', 'Support vectors highlighted.')}</div></div>`;
    omXY('op1', [sp('α = 0', res.alpha.map((a, i) => ({x: a, y: res.margin[i]})).filter(p => p.x <= 1e-8), t.ink3, {pointRadius: 2}), sp('0 < α < C (margin)', res.alpha.map((a, i) => ({x: a, y: res.margin[i]})).filter(p => p.x > 1e-8 && p.x < C - 1e-8), t.s[0], {pointRadius: 3}), sp('α = C (bound)', res.alpha.map((a, i) => ({x: a, y: res.margin[i]})).filter(p => p.x >= C - 1e-8), t.crit, {pointRadius: 2.5}), sl('y·f = 1', [{x: 0, y: 1}, {x: C, y: 1}], t.s[2], {borderDash: [4, 4], borderWidth: 1})], {xt: 'α', yt: 'y·f(x)'});
    const hb = omHist(res.alpha, 20, 0, C); opBar('op2', hb.x.map(x => opF(x, 3)), [{label: 'days', data: hb.c}]);
    mk('op3', {type: 'line', data: {labels: te.map(o => o.d), datasets: [{label: 'SVM long/flat', data: ps.curve, borderColor: t.s[0], pointRadius: 0}, {label: 'Buy & hold', data: pb.curve, borderColor: t.ink3, pointRadius: 0}]}, options: {scales: {x: {ticks: {maxTicksLimit: 8}}, y: {}}}});
    const Z = tr.map(z); omXY('op4', [sp('up, not SV', Z.filter((_, i) => tr[i].y > 0 && res.alpha[i] <= 1e-8).map(q => ({x: q[0], y: q[2]})), t.good, {pointRadius: 2}), sp('down, not SV', Z.filter((_, i) => tr[i].y < 0 && res.alpha[i] <= 1e-8).map(q => ({x: q[0], y: q[2]})), t.crit, {pointRadius: 2}), sp('support vectors', Z.filter((_, i) => res.alpha[i] > 1e-8).map(q => ({x: q[0], y: q[2]})), t.s[0], {pointRadius: 3, backgroundColor: 'transparent'})], {xt: 'r(t−1), standardised', yt: '5-day momentum, standardised'});
  }});

opDef({g: 'kkt', id: 'arb', name: 'Option no-arbitrage bounds',
  intro: `Call prices across strikes must satisfy <b>max(0, Se<sup>−qT</sup> − Ke<sup>−rT</sup>) ≤ C(K) ≤ Se<sup>−qT</sup></b>, fall with K (C(K₁) ≥ C(K₂)), with slope no steeper than −e<sup>−rT</sup>, and be <b>convex</b> in K (every butterfly spread has non-negative value). Quotes that break these allow riskless profit. The checker lists violations, then projects the quotes onto the arbitrage-free set — a quadratic programme whose KKT multipliers show which no-arbitrage constraints the corrected prices are pressed against.`,
  learn: `Projection: min ½Σ(Ĉᵢ − Cᵢ)² subject to all the linear inequalities above (interior-point QP). A positive multiplier on a convexity constraint means that butterfly is priced at exactly zero after correction — that is where the quotes were inconsistent. Puts are handled with the mirror conditions (rise with K, slope ≤ e<sup>−rT</sup>, convex).<br>Nepal has no listed equity options yet; the default quotes are <b>illustrative</b> (with one deliberate convexity break). Paste real quotes (from a broker, an OTC desk, or another market) as “strike, price” lines.`,
  symDefault: 'NEPSE',
  fields: [oN('S', 'Spot S', 100), oN('r', 'Risk-free % p.a.', 5), oN('q', 'Dividend yield % p.a.', 0), oN('T', 'Maturity (years)', 0.5), oO('type', 'Option type', 'call', [['call', 'Call'], ['put', 'Put']]), oT('quotes', 'Quotes: strike, price (one per line)', '80, 22.5\n90, 13.0\n100, 7.2\n110, 4.6\n120, 1.0')],
  run(v, out) { const rows = String(v.quotes || '').split(/\n+/).map(l => l.split(/[,;\t ]+/).map(Number)).filter(r => r.length >= 2 && isNum(r[0]) && isNum(r[1]) && r[0] > 0), t = T();
    if (rows.length < 3) throw new Error('Give at least three “strike, price” lines.'); if (new Set(rows.map(r => r[0])).size < rows.length) throw new Error('Each strike must appear once.');
    const r = OPT.arbCheck(rows.map(x => x[0]), rows.map(x => x[1]), {S0: v.S || 100, r: (v.r || 0) / 100, q: (v.q || 0) / 100, T: v.T || 0.5, type: v.type}), K = r.K;
    out.innerHTML = opKpi([['Violations in the quotes', String(r.viol.length), r.viol.length ? 'arbitrage present' : 'arbitrage-free'], ['Binding constraints after correction', String(r.binding.length), ''], ['Total squared adjustment', opF(r.sse, 4), '']])
      + opCard('Quotes, corrected arbitrage-free prices and adjustments', opTbl(['Strike', 'Quote', 'Arbitrage-free', 'Adjustment'], K.map((k, i) => [opF(k, 2), opF(r.C[i], 3), opF(r.fit[i], 3), opF(r.adj[i], 3)])))
      + opCard('Violated conditions (in the quotes)', r.viol.length ? opTbl(['Condition', 'At strike(s)', 'Shortfall'], r.viol.map(x => [esc(x.kind), x.kind.startsWith('convex') ? `${K[x.i]}–${K[x.i + 1]}–${K[x.i + 2]}` : x.kind.includes('bound') ? String(K[x.i]) : `${K[x.i]}–${K[x.i + 1]}`, opF(x.gap, 4)])) : '<p class="sub">None — the quotes are free of static arbitrage.</p>')
      + opCard('KKT multipliers of the binding constraints', r.binding.length ? opTbl(['Constraint', 'At strike(s)', 'Multiplier μ', 'Slack'], r.binding.map(x => [esc(x.kind), x.kind.startsWith('convex') ? `${K[x.i]}–${K[x.i + 1]}–${K[x.i + 2]}` : x.kind.includes('bound') ? String(K[x.i]) : `${K[x.i]}–${K[x.i + 1]}`, opF(x.z, 4), opE(x.slack)])) : '<p class="sub">No constraint binds: the quotes were already consistent.</p>', 'μ > 0 with zero slack: the corrected prices sit exactly on that no-arbitrage boundary (complementary slackness).')
      + `<div class="card wide"><div class="grid2">${opC(1, 'Price vs strike', 'Quotes, corrected prices and the static bounds.')}${opC(2, 'Butterfly spread values', 'Must be ≥ 0; negative bars are free money in the quotes.')}</div></div>`;
    const dfr = Math.exp(-(v.r || 0) / 100 * (v.T || 0.5)), dfq = Math.exp(-(v.q || 0) / 100 * (v.T || 0.5)), S0 = v.S || 100, call = v.type !== 'put';
    omXY('op1', [sp('quotes', K.map((k, i) => ({x: k, y: r.C[i]})), t.crit, {pointRadius: 5}), sl('arbitrage-free', K.map((k, i) => ({x: k, y: r.fit[i]})), t.s[0], {pointRadius: 3}), sl('lower bound', K.map(k => ({x: k, y: call ? Math.max(0, S0 * dfq - k * dfr) : Math.max(0, k * dfr - S0 * dfq)})), t.ink3, {borderDash: [4, 4], borderWidth: 1}), sl('upper bound', K.map(k => ({x: k, y: call ? S0 * dfq : k * dfr})), t.ink3, {borderDash: [2, 3], borderWidth: 1})], {xt: 'strike K', yt: 'option price'});
    const bf = c => K.slice(1, -1).map((_, i) => { const d1 = K[i + 1] - K[i], d2 = K[i + 2] - K[i + 1]; return d2 / (d1 + d2) * c[i] + d1 / (d1 + d2) * c[i + 2] - c[i + 1]; });
    opBar('op2', K.slice(1, -1).map(String), [{label: 'quotes', data: bf(r.C), color: t.crit}, {label: 'corrected', data: bf(r.fit), color: t.s[0]}], {yt: 'butterfly value'});
  }});

/* ================================== HAMILTONIAN ================================== */
opDef({g: 'ham', id: 'ac', name: 'Almgren–Chriss optimal execution',
  intro: `Selling X shares over T days moves the price against you (temporary impact η·v, permanent impact γ per share) while waiting exposes the unsold inventory to price risk. Minimising E[cost] + λ·Var[cost] is a control problem: with state x(t) (shares left) and control v = −ẋ (selling speed) the Hamiltonian <b>ℋ = ηv² + λσ²x² + p(−v)</b> gives ∂ℋ/∂v = 0 ⇒ p = 2ηv and ṗ = −∂ℋ/∂x ⇒ <b>ẍ = κ²x</b>, so <b>x(t) = X·sinh(κ(T − t))/sinh(κT)</b> with κ² = λσ²/η — front-loaded selling that decays hyperbolically. λ = 0 gives a straight line (TWAP).`,
  learn: `Discrete-time solution (Almgren & Chriss 2000): cosh(κτ) = 1 + λσ²τ²/(2η̃), η̃ = η − γτ/2. E[cost] = ½γX² + εΣ|nₖ| + (η̃/τ)Σnₖ², Var = σ²τΣxₖ². The co-state p(t) = 2ηv(t) is the marginal cost of holding one more share. Calibration (stated assumptions, edit freely): σ in Rs per share per day from the last 60 daily returns; average daily volume (ADV) = median of the last 60 days; ε = half the bid–ask spread; η set so that selling at 10% of ADV per day costs σ<sub>daily</sub>·√0.1 per share (anchored on the empirical square-root impact law); γ so that selling 10% of ADV moves the price permanently by half that. Almgren–Chriss’s own example instead used “1% of ADV costs one spread”, which is far too harsh for thin NEPSE books. NEPSE’s ±10% circuit breaker and thin order books make impact larger in practice for small-caps.`,
  symDefault: 'NABIL',
  fields: [oS('sym', 'Stock'), oN('X', 'Shares to sell (blank = auto)', null), oN('T', 'Horizon (trading days)', 5), oN('N', 'Trading periods', 20), oN('spread', 'Bid–ask spread % of price', 0.5), oN('tmp', 'Temp. impact bp at 10% ADV', null), oN('perm', 'Perm. impact bp per 10% ADV', null), oN('lam', 'Risk aversion λ (blank = auto)', null)],
  run(v, out) { const S = qSeries(v.sym), n = S.c.length; if (n < 70) throw new Error('Need at least 70 days of prices.'); const t = T();
    const P0 = S.c[n - 1], rr = []; for (let i = n - 60; i < n; i++) if (S.c[i] > 0 && S.c[i - 1] > 0) rr.push(Math.log(S.c[i] / S.c[i - 1])); const sig = ST.sd(rr) * P0;
    const vols = S.v.slice(-60).filter(x => isNum(x) && x > 1), adv = vols.length ? ST.median(vols) : null; if (!adv) throw new Error('No volume data for this symbol — upload prices with a Volume column.');
    const Td = Math.max(0.5, v.T || 5), Np = Math.max(2, Math.min(200, Math.round(v.N || 20))), X = isNum(v.X) && v.X > 0 ? v.X : Math.round(0.1 * adv * Td), spr = (v.spread || 0.5) / 100 * P0, eps = spr / 2, tmpBp = isNum(v.tmp) && v.tmp > 0 ? v.tmp : sig / P0 * Math.sqrt(0.1) * 1e4, permBp = isNum(v.perm) && v.perm >= 0 ? v.perm : tmpBp / 2, eta = tmpBp / 1e4 * P0 / (0.1 * adv), gam = permBp / 1e4 * P0 / (0.1 * adv);
    const lamBase = isNum(v.lam) && v.lam > 0 ? v.lam : 2 * eta / (sig * sig * (Td / 3) ** 2); // κT ≈ 3 by default
    const o = OPT.almgrenChriss({X, T: Td, N: Np, sigma: sig, eta, gamma: gam, eps, lam: lamBase}), tw = OPT.almgrenChriss({X, T: Td, N: Np, sigma: sig, eta, gamma: gam, eps, lam: 0});
    const imm = {EC: 0.5 * gam * X * X + eps * X + (eta - gam / 2) * X * X, SD: 0};
    out.innerHTML = opKpi([['Price · σ per day', `Rs ${opF(P0, 1)} · Rs ${opF(sig, 2)}`, `ADV ${fmt(adv, 0)} shares`], ['Order', `${fmt(X, 0)} shares`, `${opF(X / adv * 100, 0)}% of ADV, Rs ${fmt(X * P0, 0)}`], ['κ · half-life', `${opF(o.kap, 3)} · ${isFinite(o.halfLife) ? opF(o.halfLife, 2) + ' days' : '–'}`, 'λ = ' + opE(lamBase)], ['Optimal: E[cost] ± SD', `Rs ${fmt(o.EC, 0)} ± ${fmt(o.SD, 0)}`, `${opF(o.EC / (X * P0) * 1e4, 1)} bp of value`], ['TWAP (λ = 0)', `Rs ${fmt(tw.EC, 0)} ± ${fmt(tw.SD, 0)}`, `all at once: Rs ${fmt(imm.EC, 0)}`]])
      + opCard('Optimal schedule', opTbl(['Period', 'Time (days)', 'Shares held after', 'Sell in period', 'Speed (shares/day)', 'Co-state p = 2ηv (Rs/share)'], o.n.map((nk, j) => [j + 1, opF(o.t[j + 1], 2), fmt(o.x[j + 1], 0), fmt(nk, 0), fmt(o.v[j], 0), opF(2 * eta * o.v[j], 3)])), `Calibrated: ε = Rs ${opF(eps, 3)} (half-spread); η = ${opE(eta)} (selling 10% of ADV per day costs ${opF(tmpBp, 1)} bp); γ = ${opE(gam)} (selling 10% of ADV moves the price ${opF(permBp, 1)} bp for good). These are assumptions — see Learn.`)
      + `<div class="card wide"><div class="grid2">${opC(1, 'Inventory trajectories x(t)', 'Higher risk aversion ⇒ faster, more front-loaded selling.')}${opC(2, 'Efficient frontier of execution', 'Each point is the optimum for one λ.')}${opC(3, 'Co-state p(t): marginal cost of inventory', 'From the Hamiltonian: p = 2ηv.')}${opC(4, 'Simulated implementation shortfall', '2,000 price paths, same shocks for both schedules.')}</div></div>`;
    const lams = [0, 0.1, 0.3, 1, 3, 10].map(f => f * lamBase), cols = [t.ink3, t.s[1], t.s[2], t.s[0], t.s[4], t.crit];
    omXY('op1', lams.map((l, i) => { const q = OPT.almgrenChriss({X, T: Td, N: Np, sigma: sig, eta, gamma: gam, eps, lam: l}); return sl(i ? `λ×${[0, 0.1, 0.3, 1, 3, 10][i]}` : 'TWAP (λ=0)', q.t.map((tt, j) => ({x: tt, y: q.x[j]})), cols[i], {pointRadius: 2, borderWidth: i === 3 ? 3 : 1.5}); }), {xt: 'days', yt: 'shares held', d: 2});
    const fr = Array.from({length: 40}, (_, i) => lamBase * Math.pow(10, -3 + i * 5 / 39)).map(l => OPT.almgrenChriss({X, T: Td, N: Np, sigma: sig, eta, gamma: gam, eps, lam: l}));
    omXY('op2', [sl('frontier', [tw, ...fr].map(q => ({x: q.SD, y: q.EC})), t.s[0]), sp('chosen λ', [{x: o.SD, y: o.EC}], t.crit, {pointRadius: 7}), sp('TWAP', [{x: tw.SD, y: tw.EC}], t.ink3, {pointRadius: 6})], {xt: 'SD of cost (Rs)', yt: 'expected cost (Rs)', d: 0});
    omXY('op3', [sl('p(t), chosen λ', o.t.map((tt, j) => ({x: tt, y: o.p[j]})), t.s[0]), sl('p(t), TWAP', tw.t.map((tt, j) => ({x: tt, y: tw.p[j]})), t.ink3, {borderDash: [4, 4]})], {xt: 'days', yt: 'Rs per share'});
    const s1 = OPT.acSimulate(o, {S0: P0, sigma: sig, eta, gamma: gam, eps}), s2 = OPT.acSimulate(tw, {S0: P0, sigma: sig, eta, gamma: gam, eps}), lo = Math.min(...s1, ...s2), hi = Math.max(...s1, ...s2), h1 = omHist(s1, 40, lo, hi), h2 = omHist(s2, 40, lo, hi);
    mk('op4', {type: 'bar', data: {labels: h1.x.map(x => fmt(x, 0)), datasets: [{label: 'optimal', data: h1.c, backgroundColor: t.s[0] + 'aa'}, {label: 'TWAP', data: h2.c, backgroundColor: t.ink3 + '88'}]}, options: {scales: {x: {ticks: {maxTicksLimit: 8}, title: {display: true, text: 'shortfall (Rs)'}}, y: {}}}});
  }});

opDef({g: 'ham', id: 'merton', name: 'Merton portfolio & consumption',
  intro: `An investor splits wealth W between a risk-free asset (rate r) and a stock (μ, σ) and chooses consumption c to maximise E[∫e<sup>−ρt</sup>u(c)dt + e<sup>−ρT</sup>u(W<sub>T</sub>)] with CRRA utility u(c) = c<sup>1−γ</sup>/(1−γ). The stochastic Hamiltonian / <b>Hamilton–Jacobi–Bellman</b> equation V<sub>t</sub> + max<sub>c,π</sub>[e<sup>−ρt</sup>u(c) + V<sub>W</sub>(rW + π(μ−r)W − c) + ½V<sub>WW</sub>π²σ²W²] = 0 gives <b>π* = (μ − r)/(γσ²)</b> (a constant share in the stock) and consumption c* = W/f(t), f(t) = [1 + (ν − 1)e<sup>−ν(T−t)</sup>]/ν.`,
  learn: `ν = [ρ − (1−γ)(r + (μ−r)²/(2γσ²))]/γ. The value function is V = e<sup>−ρt</sup>f(t)<sup>γ</sup>W<sup>1−γ</sup>/(1−γ); the app plugs it back into the HJB equation and reports the residual (≈ 0 confirms the solution). μ and σ are estimated from the chosen stock or index (annualised ×240) and can be overridden; the default risk-free rate is the latest 91-day T-bill rate. Historical NEPSE means are noisy, so π* can be extreme or negative — the “no leverage / no short” option caps it to [0, 1] for the simulation. Certainty-equivalent wealth compares strategies on the same utility scale.`,
  symDefault: 'NEPSE',
  fields: [oS('sym', 'Stock / index for μ and σ'), oN('n', 'Estimation window (days, 0 = all)', 0), oN('mu', 'Override μ % p.a.', null), oN('sigma', 'Override σ % p.a.', null), oN('rf', 'Risk-free % p.a.', () => +opF(sqRf(), 2)), oN('gamma', 'Risk aversion γ', 3), oN('rho', 'Time preference ρ % p.a.', 3), oN('T', 'Horizon (years)', 20), oN('W0', 'Initial wealth (Rs)', 1000000), oO('cap', 'Simulation', 'cap', [['cap', 'No leverage / no short (π in [0,1])'], ['free', 'Unconstrained π*']])],
  run(v, out) { const t = T(); let mu = isNum(v.mu) ? v.mu / 100 : null, sig = isNum(v.sigma) && v.sigma > 0 ? v.sigma / 100 : null;
    if (mu === null || sig === null) { const {r} = sqRet(v.sym, v.n > 0 ? v.n : 0); if (r.length < 120) throw new Error('Need at least 120 daily returns.'); const m = ST.mean(r) / 100, s = ST.sd(r) / 100; if (mu === null) mu = m * 240 + 0.5 * s * s * 240; if (sig === null) sig = s * Math.sqrt(240); }
    const r0 = (v.rf || 0) / 100, gm = Math.max(0.2, v.gamma || 3), rho = (v.rho || 0) / 100, Tm = Math.max(1, v.T || 20), W0 = v.W0 || 1e6;
    if (Math.abs(gm - 1) < 1e-6) throw new Error('Use γ ≠ 1 (log utility is the limit γ → 1; try 1.01).');
    const o = OPT.merton({mu, r: r0, sigma: sig, gamma: gm, rho, T: Tm}), piSim = v.cap === 'cap' ? Math.min(1, Math.max(0, o.pi)) : o.pi;
    const sims = [['Merton π*' + (v.cap === 'cap' && piSim !== o.pi ? ' (capped)' : ''), piSim], ['100% stock', 1], ['0% stock (all risk-free)', 0]].map(([l, p]) => ({l, p, s: OPT.mertonSim(o, {mu, r: r0, sigma: sig, gamma: gm, rho, T: Tm, W0, steps: Math.round(Tm * 12), paths: 800, piOverride: p})}));
    const hj = [[0, W0], [Tm / 2, W0 * 2], [Tm * 0.9, W0 / 2]].map(([tt, w]) => Math.abs(o.hjb(tt, w)));
    out.innerHTML = opKpi([['μ · σ (p.a.)', `${opF(mu * 100, 2)}% · ${opF(sig * 100, 2)}%`, `risk-free ${opF(r0 * 100, 2)}%`], ['π* = (μ−r)/(γσ²)', opF(o.pi * 100, 1) + '% in stock', o.pi > 1 ? 'leveraged' : o.pi < 0 ? 'short the stock' : ''], ['Consume now', opF(100 / o.f(0), 2) + '% of wealth p.a.', 'c/W = 1/f(0)'], ['ν', opF(o.nu, 4), ''], ['HJB residual', opE(Math.max(...hj)), 'relative, at 3 (t, W) points']])
      + opCard('Strategies compared (simulated)', opTbl(['Strategy', 'Stock share', 'Median terminal wealth', '5th percentile', '95th percentile', 'Mean discounted utility'], sims.map(x => { const term = x.s.W.map(p => p[p.length - 1]); return [esc(x.l), opF(x.p * 100, 1) + '%', fmt(ST.median(term), 0), fmt(ST.quantile(term, 0.05), 0), fmt(ST.quantile(term, 0.95), 0), opE(ST.mean(x.s.util))]; })), 'Each uses the optimal consumption rule c = W/f(t); 800 paths, monthly steps. The Merton share has the highest expected utility (up to simulation noise) when unconstrained.')
      + `<div class="card wide"><div class="grid2">${opC(1, 'Optimal stock share π* vs risk aversion γ', 'π* falls as 1/γ.')}${opC(2, 'Consumption rate c/W over the horizon', 'Rises as the horizon shortens (less left to save for).')}${opC(3, 'Wealth fan under the simulated Merton rule', 'Median and 5–95% band.')}${opC(4, 'Value function V(0, W)', 'Concave in wealth: CRRA utility.')}</div></div>`;
    omXY('op1', [sl('π*', opRng(0.5, 10, 60).map(g => ({x: g, y: 100 * (mu - r0) / (g * sig * sig)})), t.s[0]), sp('your γ', [{x: gm, y: o.pi * 100}], t.crit, {pointRadius: 6})], {xt: 'γ', yt: 'stock share %', legend: false});
    omXY('op2', [sl('c/W', opRng(0, Tm * 0.999, 60).map(tt => ({x: tt, y: 100 / o.f(tt)})), t.s[1])], {xt: 'years', yt: '% of wealth per year', legend: false});
    const W = sims[0].s.W, steps = W[0].length, q = p => Array.from({length: steps}, (_, i) => ST.quantile(W.map(w => w[i]), p)), xs2 = Array.from({length: steps}, (_, i) => i / 12);
    omXY('op3', [sl('95th', xs2.map((x, i) => ({x, y: q(0.95)[i]})), t.s[2], {borderWidth: 1}), sl('median', xs2.map((x, i) => ({x, y: q(0.5)[i]})), t.s[0]), sl('5th', xs2.map((x, i) => ({x, y: q(0.05)[i]})), t.crit, {borderWidth: 1})], {xt: 'years', yt: 'wealth (Rs)', d: 0});
    omXY('op4', [sl('V(0,W)', opRng(W0 * 0.1, W0 * 3, 60).map(w => ({x: w, y: o.V(0, w)})), t.s[4])], {xt: 'wealth (Rs)', yt: 'value', legend: false, d: 0});
  }});

opDef({g: 'ham', id: 'ramsey', name: 'Ramsey–Cass–Koopmans growth',
  intro: `The benchmark model behind DSGE macro: a planner chooses consumption to maximise ∫e<sup>−(ρ−n)t</sup>c<sup>1−θ</sup>/(1−θ)dt subject to capital accumulation k̇ = k<sup>α</sup> − c − (n + g + δ)k (per effective worker). Current-value Hamiltonian <b>ℋ = u(c) + μ[k<sup>α</sup> − c − (n+g+δ)k]</b>: ∂ℋ/∂c = 0 ⇒ μ = c<sup>−θ</sup> (the co-state is the shadow value of capital), and μ̇ = (ρ…)μ − ∂ℋ/∂k gives the Euler equation <b>ċ/c = (αk<sup>α−1</sup> − δ − ρ − θg)/θ</b>. With transversality, the economy follows the unique <b>saddle path</b> to the steady state.`,
  learn: `Steady state: k* = [α/(δ + ρ + θg)]<sup>1/(1−α)</sup>, c* = k*<sup>α</sup> − (n+g+δ)k* — below the golden-rule capital stock because the future is discounted. The saddle path is found by shooting (bisection on c₀ until the path neither collapses nor overshoots) and, for the phase diagram, by integrating backward along the stable eigenvector of the linearised system; the stable eigenvalue is the speed of convergence.<br><b>Nepal context:</b> the reference panel shows Nepal’s average real GDP growth from the app’s data; with population growth near 1% (2021 census: about 0.9% a year) and capital shares typically estimated around 0.3–0.4 for developing economies, the parameters can be set to explore how faster capital deepening (higher k₀/k*) or patience (lower ρ) changes the transition. Parameters are user assumptions, not estimates.`,
  fields: [oN('alpha', 'Capital share α', 0.33), oN('delta', 'Depreciation δ', 0.05), oN('rho', 'Discount rate ρ', 0.03), oN('theta', 'Inverse IES θ', 2), oN('n', 'Population growth n', 0.009), oN('g', 'Technology growth g', 0.02), oN('k0', 'Starting capital k₀ / k*', 0.5)],
  run(v, out) { const t = T(), r = OPT.ramsey({alpha: v.alpha, delta: v.delta, rho: v.rho, theta: v.theta, n: v.n, g: v.g, k0: Math.max(0.05, v.k0 || 0.5)});
    const gl = ds('gdp_long'), gr = gl ? gl.rows.filter(x => isNum(x.real_g)).slice(-10).map(x => x.real_g) : [], avg = gr.length ? ST.mean(gr) : null;
    out.innerHTML = opKpi([['Steady state k* · c*', `${opF(r.ks, 3)} · ${opF(r.cs, 3)}`, `output y* = ${opF(r.ys, 3)}`], ['Saving rate s*', opF(r.sr * 100, 1) + '%', `golden-rule k = ${opF(r.kGold, 3)}`], ['Real interest r* = f′(k*) − δ', opF(r.rStar * 100, 2) + '%', '= ρ + θg'], ['Convergence speed', opF(-r.lamS * 100, 2) + '% a year', `half-way in ≈ ${r.tHalf ? opF(r.tHalf, 1) : '–'} years`], ['Nepal reference', avg !== null ? opF(avg, 2) + '%' : '–', 'average real GDP growth, last 10 years']])
      + opCard('Transition path (saddle path from k₀)', opTbl(['Year', 'k', 'c', 'y = k^α', 'saving rate', 'co-state μ = c^−θ'], [0, 5, 10, 20, 30, 50, 80].map(yr => { const p = r.path.reduce((a, b) => Math.abs(b.t - yr) < Math.abs(a.t - yr) ? b : a); return [opF(p.t, 0), opF(p.k, 3), opF(p.c, 3), opF(p.k ** v.alpha, 3), opF((1 - p.c / p.k ** v.alpha) * 100, 1) + '%', opF(p.c ** -v.theta, 3)]; })), `Initial consumption on the saddle path c₀ = ${opF(r.c0, 4)} (found by shooting).`)
      + `<div class="card wide"><div class="grid2">${opC(1, 'Phase diagram', 'k̇ = 0 locus, ċ = 0 line, saddle path and the economy’s path from k₀.')}${opC(2, 'Capital and consumption over time', 'Per effective worker.')}${opC(3, 'Co-state μ(t) = c^−θ', 'Shadow value of capital: falls as capital becomes abundant.')}${opC(4, 'Saving rate and interest rate on the path', '')}</div></div>`;
    const kmax = Math.max(2.2 * r.ks, r.kGold * 1.3), kk = opRng(1e-3, kmax, 120);
    omXY('op1', [sl('k̇ = 0', kk.map(k => ({x: k, y: r.kdot0(k)})).filter(p => p.y > 0), t.s[1]), sl('ċ = 0', [{x: r.ks, y: 0}, {x: r.ks, y: Math.max(...kk.map(r.kdot0)) * 1.2}], t.s[2]), sl('saddle path', r.manifold.filter(p => p.k < kmax && p.c < Math.max(...kk.map(r.kdot0)) * 1.3).map(p => ({x: p.k, y: p.c})), t.s[0], {borderWidth: 2.5}), sp('steady state', [{x: r.ks, y: r.cs}], t.crit, {pointRadius: 7}), sp('start', [{x: r.path[0].k, y: r.path[0].c}], t.s[4], {pointRadius: 6}), sl('path from k₀', r.path.filter((_, i) => i % 5 === 0).map(p => ({x: p.k, y: p.c})), t.s[4], {borderWidth: 1.5, borderDash: [2, 2]}), sl('golden rule k', [{x: r.kGold, y: 0}, {x: r.kGold, y: r.kdot0(r.kGold)}], t.ink3, {borderDash: [4, 4], borderWidth: 1})], {xt: 'k (capital per effective worker)', yt: 'c'});
    const pp = r.path.filter((_, i) => i % 4 === 0);
    omXY('op2', [sl('k', pp.map(p => ({x: p.t, y: p.k})), t.s[0]), sl('c', pp.map(p => ({x: p.t, y: p.c})), t.s[1]), sl('k*', [{x: 0, y: r.ks}, {x: pp[pp.length - 1].t, y: r.ks}], t.s[0], {borderDash: [4, 4], borderWidth: 1}), sl('c*', [{x: 0, y: r.cs}, {x: pp[pp.length - 1].t, y: r.cs}], t.s[1], {borderDash: [4, 4], borderWidth: 1})], {xt: 'years', yt: 'level'});
    omXY('op3', [sl('μ = c^−θ', pp.map(p => ({x: p.t, y: p.c ** -v.theta})), t.s[4])], {xt: 'years', yt: 'shadow value of capital', legend: false});
    omXY('op4', [sl('saving rate %', pp.map(p => ({x: p.t, y: 100 * (1 - p.c / p.k ** v.alpha)})), t.s[2]), sl('r = f′(k) − δ, %', pp.map(p => ({x: p.t, y: 100 * (v.alpha * p.k ** (v.alpha - 1) - v.delta)})), t.s[3])], {xt: 'years', yt: '%'});
  }});

opDef({g: 'ham', id: 'amer', name: 'American option (optimal stopping)',
  intro: `An American option can be exercised at any time, so its value solves a stochastic control (optimal stopping) problem: V = sup<sub>τ</sub> E[e<sup>−rτ</sup>payoff(S<sub>τ</sub>)]. In continuous time this is a <b>linear complementarity problem</b> — the dynamic analogue of KKT: V ≥ payoff, ∂V/∂t + ℒV ≤ 0 and (V − payoff)(∂V/∂t + ℒV) = 0. Where exercise is optimal V equals the payoff; elsewhere V satisfies Black–Scholes. The boundary between the regions, S*(t), is the <b>early-exercise boundary</b>.`,
  learn: `Solved by backward dynamic programming on a Cox–Ross–Rubinstein tree (Bellman: V = max(payoff, discounted expected continuation)) and cross-checked with a Crank–Nicolson finite-difference solver. The tree also verifies complementarity at every node. Smooth pasting: the American value meets the payoff tangentially at S*. σ comes from the chosen symbol (last 250 days, annualised) unless overridden; S defaults to the last price and K to S. American calls on non-dividend stocks are never exercised early (premium ≈ 0); puts and dividend-paying calls are.`,
  symDefault: 'NEPSE',
  fields: [oS('sym', 'Underlying (for S and σ)'), oN('S', 'Spot S (blank = last price)', null), oN('K', 'Strike K (blank = S)', null), oN('T', 'Maturity (years)', 1), oN('r', 'Risk-free % p.a.', () => +opF(sqRf(), 2)), oN('q', 'Dividend yield % p.a.', 0), oN('sig', 'Volatility % p.a. (blank = estimate)', null), oO('type', 'Type', 'put', [['put', 'Put'], ['call', 'Call']]), oN('steps', 'Tree steps', 600)],
  run(v, out) { const t = T(), Sx = qSeries(v.sym), S0 = isNum(v.S) && v.S > 0 ? v.S : Sx.c[Sx.c.length - 1], K = isNum(v.K) && v.K > 0 ? v.K : S0;
    let sig = isNum(v.sig) && v.sig > 0 ? v.sig / 100 : null; if (!sig) { const {r} = sqRet(v.sym, 250); sig = ST.sd(r) / 100 * Math.sqrt(240); }
    const o = {S: S0, K, T: Math.max(1 / 365, v.T || 1), r: (v.r || 0) / 100, q: (v.q || 0) / 100, sigma: sig, type: v.type, steps: Math.max(50, Math.min(3000, Math.round(v.steps || 600)))}, a = OPT.american(o);
    let fd = null; try { fd = QF.finiteDiff({...o, american: true, scheme: 'cn', NS: 300, NT: 600}); fd = isNum(fd) ? fd : fd?.price; } catch (e) {}
    const bs = QF.bs({...o}).price;
    out.innerHTML = opKpi([['American value', opF(a.price, 4), `S ${opF(S0, 2)}, K ${opF(K, 2)}, σ ${opF(sig * 100, 1)}%`], ['European (Black–Scholes)', opF(bs, 4), 'tree: ' + opF(a.euro, 4)], ['Early-exercise premium', opF(a.price - bs, 4), opF((a.price - bs) / (bs || 1) * 100, 2) + '% of European'], ['Finite-difference check', fd !== null ? opF(fd, 4) : '–', 'Crank–Nicolson with exercise'], ['Complementarity residual', opE(a.maxLcp), 'max |(V−payoff)(V−continuation)| over nodes']])
      + `<div class="card wide"><div class="grid2">${opC(1, 'Early-exercise boundary S*(t)', a.boundary.length ? (v.type === 'put' ? 'Exercise when S falls below the line.' : 'Exercise when S rises above the line.') : 'No early exercise is optimal for these inputs.')}${opC(2, 'Value today vs spot: smooth pasting', 'American (solid) touches the payoff tangentially at S*; European can fall below the payoff.')}</div></div>`;
    if (a.boundary.length) omXY('op1', [sl('S*(t)', a.boundary.filter((_, i) => i % Math.max(1, Math.floor(a.boundary.length / 200)) === 0).map(b => ({x: b.t, y: b.S})), t.s[0]), sl('strike', [{x: 0, y: K}, {x: o.T, y: K}], t.ink3, {borderDash: [4, 4], borderWidth: 1})], {xt: 'time (years)', yt: 'stock price', legend: false});
    const Ss = opRng(S0 * 0.5, S0 * 1.5, 41), am = OPT.americanCurve({...o, steps: 300}, Ss), pay = s => v.type === 'call' ? Math.max(s - K, 0) : Math.max(K - s, 0);
    omXY('op2', [sl('American', am.map(p => ({x: p.S, y: p.am})), t.s[0]), sl('European', Ss.map(s => ({x: s, y: QF.bs({...o, S: s}).price})), t.s[1], {borderDash: [5, 4]}), sl('payoff', Ss.map(s => ({x: s, y: pay(s)})), t.ink3, {borderWidth: 1})], {xt: 'spot S', yt: 'option value'});
  }});
